on conflict (id) do update set
  name = excluded.name,
  country = excluded.country,
  city = excluded.city,
  neighborhood = excluded.neighborhood,
  coordinates = excluded.coordinates,
  photo = coalesce(excluded.photo, public.editorial_pois.photo),
  guide_ids = excluded.guide_ids,
  guide_slugs = excluded.guide_slugs,
  categories = excluded.categories;

insert into public.editorial_guides (
  id,
  slug,
  category,
  country,
  city,
  neighborhood,
  list
)
values
  ('list-paris-1st-arrondissement-restaurants', 'paris-1st-arrondissement-restaurants', 'Food', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-restaurants","slug":"paris-1st-arrondissement-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in 1st Arrondissement, Paris","seoDescription":"Best restaurants in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Museum-Day Meals Around the Royal Core","description":"The 1st needs meals that can survive Louvre timing, Tuileries walks, and central crowds. This guide mixes tea-room ritual, udon, polished dining, and a classic cafe so the day has food options without leaving the royal core.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-food-angelina","name":"Angelina","coordinates":[48.8651,2.3286],"description":"Angelina is the Tuileries-side tea-room ritual for hot chocolate, pastries, and a seated pause between the Louvre, Rue de Rivoli, and Concorde. Use it when the stop is about classic Paris room tone as much as sugar.","price":"$$","priceSource":"Google Maps / Paris dining guides","photo":"https://cdn.prod.website-files.com/6393398914410c453e1df00f/69f391d9f6605f6780643f62_MADEMOISELLE_ANGELINA_CARTE_PE_2026_PACKSHOT_%C2%A9_MARY_DEVINAT_16-compressed.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-angelina"},{"id":"first-food-sanukiya","name":"Sanukiya","coordinates":[48.8648,2.3339],"description":"Sanukiya gives the 1st a practical Japanese noodle stop near Pyramides, useful when the day needs speed, warmth, and value instead of another long French meal. It is best for lunch windows around Palais Royal or the Louvre.","price":"$","priceSource":"Google Maps / Paris dining guides","photo":"https://img.restaurantguru.com/w550/h367/rb53-design-Sanukiya-2022-09-4.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-sanukiya"},{"id":"first-food-verjus","name":"Verjus","coordinates":[48.8634,2.3381],"description":"Verjus is the small reservation dinner for travelers who want the Louvre area to end with a proper modern meal rather than a tourist-corridor compromise. Save it for a more deliberate evening near Palais Royal.","price":"$$$","priceSource":"MICHELIN Guide / Google Maps","photo":"https://images.squarespace-cdn.com/content/v1/59d4c7672278e78c2beb5c7b/1768840986895-PJ5F08GTQAKW9VDIBP48/08-AmuseBouches.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-verjus"},{"id":"first-food-le-nemours","name":"Le Nemours","coordinates":[48.8639,2.3359],"description":"Le Nemours is the cafe-brasserie hinge between the Louvre, Palais Royal, and Comedie-Francaise. It works for breakfast, coffee, or a simple lunch when location and terrace rhythm matter more than discovery.","price":"$$","priceSource":"Google Maps / local dining guides","photo":"https://www.lenemours.paris/themes/le-nemours2/img/bg-restaurant.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-le-nemours"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-1st-arrondissement-bars', 'paris-1st-arrondissement-bars', 'Nightlife', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-bars","slug":"paris-1st-arrondissement-bars","seoSlug":"best-bars","seoTitle":"Best Bars in 1st Arrondissement, Paris","seoDescription":"Best bars in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Central Cocktails and Museum-Edge Bars","description":"Nights in the 1st work best as a polished first or final drink near galleries, passages, and palace hotels. This guide keeps the route central with cocktail rooms, hotel bars, and cafe-bars that do not pull the night across town.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-nightlife-danico","name":"Danico","coordinates":[48.8666,2.3399],"description":"Danico is the Galerie Vivienne cocktail destination with World 50 Best support and a hidden-room feel that fits a polished Right Bank night. Use it when the evening needs one serious drink near Palais Royal or Bourse.","price":"$$$","priceSource":"World''s 50 Best Bars / Google Maps","photo":"https://www.daroco.com/wp-content/uploads/2024/02/AM2A5871-2100x1400.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-danico"},{"id":"first-nightlife-bar-228","name":"Bar 228","coordinates":[48.865,2.3286],"description":"Bar 228 at Le Meurice gives the Tuileries edge a grand-hotel drink with dark wood, deep seats, and classic service. It is strongest for a special-occasion nightcap after museums, dinner, or a river walk.","price":"$$$","priceSource":"Official hotel site / Google Maps","photo":"https://upload.wikimedia.org/wikipedia/commons/9/9f/Le_Meurice14.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-bar-228"},{"id":"first-nightlife-le-fumoir","name":"Le Fumoir","coordinates":[48.8606,2.3407],"description":"Le Fumoir is the Louvre-adjacent cocktail and wine-room fallback that still feels composed enough for a central night. Save it for a drink that can follow the museum without turning into a full bar crawl.","price":"$$","priceSource":"Google Maps / local nightlife guides","photo":"https://www.lefumoir.com/wp-content/uploads/2021/08/bg_0-300x199.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-fumoir"},{"id":"first-nightlife-juveniles","name":"Juveniles","coordinates":[48.8669,2.3373],"description":"Juveniles is the wine-bar and small-plates option that keeps the covered-passage area relaxed. It works when the plan wants bottles, food, and conversation instead of a formal hotel bar.","price":"$$","priceSource":"Google Maps / local wine guides","photo":"https://images.squarespace-cdn.com/content/v1/56c59d0327d4bd568aa24071/1724845110981-KYTZ5BXJL4EZ0RASJQ4O/IMG_0302.jpeg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-juveniles"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-1st-arrondissement-parks-and-walks', 'paris-1st-arrondissement-parks-and-walks', 'Nature', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-parks-and-walks","slug":"paris-1st-arrondissement-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in 1st Arrondissement, Paris","seoDescription":"Best parks and walks in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Gardens, River Edges, and Central Air","description":"Nature in the 1st is not wilderness; it is the breathing room around heavyweight sights. This guide links palace gardens, island edges, and the Seine so museum days can reset without adding another metro ride.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-nature-tuileries","name":"Jardin des Tuileries","coordinates":[48.8635,2.327],"description":"Jardin des Tuileries turns the Louvre-Orangerie corridor into a paced walk with chairs, fountains, and broad sightlines. Use it between timed tickets or as the soft landing after a crowded museum block.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-des-tuileries"},{"id":"first-nature-palais-royal-garden","name":"Jardin du Palais Royal","coordinates":[48.8637,2.3377],"description":"Jardin du Palais Royal is the quieter garden pause behind arcades and columns, useful when the Louvre side feels too exposed. It is a compact reset before covered passages, shopping, or dinner.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-du-palais-royal"},{"id":"first-nature-vert-galant","name":"Square du Vert-Galant","coordinates":[48.8571,2.3413],"description":"Square du Vert-Galant gives the 1st a low island viewpoint at the tip of Ile de la Cite. Use it for a short Seine pause between Sainte-Chapelle, Pont Neuf, and the Louvre.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-du-vert-galant"},{"id":"first-nature-seine-quays","name":"Seine Quays by the Louvre","coordinates":[48.8589,2.3408],"description":"The Seine quays make the 1st feel walkable instead of monument-heavy, especially between Pont Neuf, the Louvre, and Orsay views. Save this stop when the route needs light, orientation, and movement.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-seine-quays-by-the-louvre"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-1st-arrondissement-culture', 'paris-1st-arrondissement-culture', 'Culture', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-culture","slug":"paris-1st-arrondissement-culture","seoSlug":"best-culture","seoTitle":"Best Culture in 1st Arrondissement, Paris","seoDescription":"Best culture in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Royal Core and Museum Weight","description":"The 1st can overload a day if the Louvre is treated as the only point. This guide links the museum with Palais Royal, Orangerie, Sainte-Chapelle, and the surrounding gardens so the central core feels routeable.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-culture-louvre","name":"Musee du Louvre","coordinates":[48.8606,2.3376],"description":"The Louvre is the 1st Arrondissement heavyweight, but it works best as a bounded museum plan rather than a full-day endurance test. Choose a wing, book a time slot, and leave room for the garden or Palais Royal.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-du-louvre"},{"id":"first-culture-palais-royal","name":"Palais Royal","coordinates":[48.8637,2.3377],"description":"Palais Royal gives the Louvre area a quieter architectural and garden pause, with arcades, columns, and a clean route toward covered passages. It is useful when the district needs a reset without leaving the core.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-palais-royal"},{"id":"first-culture-orangerie","name":"Musee de l''Orangerie","coordinates":[48.8638,2.3227],"description":"Musee de l''Orangerie is the compact art stop that can balance or replace a larger museum block. Monet''s rooms and the Tuileries setting make it a powerful but manageable cultural anchor.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-de-l-orangerie"},{"id":"first-culture-sainte-chapelle","name":"Sainte-Chapelle","coordinates":[48.8554,2.345],"description":"Sainte-Chapelle adds a short, high-impact Gothic stop on the Ile de la Cite edge of the 1st. Timed entry helps it pair cleanly with the Louvre, Conciergerie, river walks, or a Marais continuation.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-sainte-chapelle"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-1st-arrondissement-hotels-and-hostels', 'paris-1st-arrondissement-hotels-and-hostels', 'Stay', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-hotels-and-hostels","slug":"paris-1st-arrondissement-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in 1st Arrondissement, Paris","seoDescription":"Best hotels and hostels in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Palace Hotels and Central Sleep","description":"Staying in the 1st is about paying for centrality: palace service, Louvre access, shopping arcades, and short walks to the Seine. This guide keeps the picks honest for travelers who want the hotel to be part of the trip.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-stay-cheval-blanc","name":"Cheval Blanc Paris","coordinates":[48.8588,2.342],"description":"Cheval Blanc Paris is the Seine-facing luxury base for travelers who want palace-level service, Samaritaine access, and immediate Right Bank positioning. It is best when the hotel experience matters as much as the route.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://images.prismic.io/lvmh-chevalblanc/Z9AApRsAHJWomUFu_WebRGB-ChevalBlancParis_SuiteSeine_Jardind%27Hiver_511_VincentLeroux.jpg?auto=format,compress","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-cheval-blanc-paris"},{"id":"first-stay-le-meurice","name":"Le Meurice","coordinates":[48.865,2.3286],"description":"Le Meurice gives the 1st classic palace gravity on Rue de Rivoli, with Tuileries and the Louvre almost outside the door. Choose it for grand-service travel and museum-heavy days.","price":"$$$","priceSource":"Official hotel site / Google Travel","photo":"https://upload.wikimedia.org/wikipedia/commons/b/ba/H%C3%B4tel_Le_Meurice.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-le-meurice"},{"id":"first-stay-regina-louvre","name":"Hotel Regina Louvre","coordinates":[48.8638,2.3322],"description":"Hotel Regina Louvre is the heritage stay for travelers who want Tuileries, Palais Royal, and Louvre access without the newest design-hotel mood. It fits first-time Paris routes that prize address and view corridors.","price":"$$$","priceSource":"Google Travel / Tripadvisor","photo":"https://hapi.mmcreation.com/hapidam/4d367904-2f7f-496a-9dcd-f7ef8e2734d0/2020_PH_V2.png.png","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-regina-louvre"},{"id":"first-stay-madame-reve","name":"Hotel Madame Reve","coordinates":[48.8626,2.3428],"description":"Hotel Madame Reve gives the 1st a newer design-led base in the former post-office building near Les Halles and the Louvre. It works when central access, rooftop energy, and contemporary rooms matter.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://madamereve.com/wp-content/uploads/2021/10/Balise_og_madame-reve.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-madame-reve"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-1st-arrondissement-things-to-do', 'paris-1st-arrondissement-things-to-do', 'Activities', 'France', 'Paris', '1st Arrondissement', '{"id":"list-paris-1st-arrondissement-things-to-do","slug":"paris-1st-arrondissement-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in 1st Arrondissement, Paris","seoDescription":"Best things to do in 1st Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"A Central Day That Does Not Spiral","description":"The 1st is strongest when it becomes a tight route rather than a list of famous errands. This guide groups museum time, gardens, island glass, passages, and Seine walks into manageable activity blocks.","url":"https://www.google.com/maps/search/1st%20Arrondissement%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"1st Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"first-activity-louvre-tuileries","name":"Louvre and Tuileries Block","coordinates":[48.8612,2.3376],"description":"The Louvre and Tuileries block is the central activity anchor: one planned museum theme, then garden air and a clean westward walk. Use it as a half-day structure instead of trying to solve the whole museum.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-louvre-and-tuileries-block"},{"id":"first-activity-sainte-chapelle-cite","name":"Sainte-Chapelle and Ile de la Cite","coordinates":[48.8554,2.345],"description":"Sainte-Chapelle and Ile de la Cite turn the edge of the 1st into a short Gothic-and-river activity. It is best with timed entry, Pont Neuf, and a slow move back toward the Louvre.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-sainte-chapelle-and-ile-de-la-cite"},{"id":"first-activity-palais-royal-passages","name":"Palais Royal and Covered Passages","coordinates":[48.8642,2.3381],"description":"Palais Royal and the nearby covered passages make a weather-proof walk with arcades, shops, and architecture. Use it when the day needs detail and browsing after a major sight.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-palais-royal-and-covered-passages"},{"id":"first-activity-samaritaine-seine","name":"Samaritaine and the Seine","coordinates":[48.8591,2.3426],"description":"Samaritaine and the Seine give the 1st a shopping-and-river activity that stays compact. It works for a lighter block between meals, hotel check-in, and central evening plans.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-samaritaine-and-the-seine"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-restaurants', 'paris-le-marais-restaurants', 'Food', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-restaurants","slug":"paris-le-marais-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Le Marais, Paris","seoDescription":"Best restaurants in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Old-Quarter Meals With a Point","description":"Le Marais food works when each stop has a job: a bistro, falafel counter, market lunch, or polished wine-led room. This guide keeps the old quarter from becoming only boutiques, dessert lines, and vague cafe wandering.","url":"https://www.google.com/maps/search/Le%20Marais%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-food-bistrot-tournelles","name":"Bistrot des Tournelles","coordinates":[48.8555,2.366],"description":"Bistrot des Tournelles is the Marais bistro pick for travelers who want a real sit-down meal near Place des Vosges. The throwback room and classic plates make it useful when the neighborhood needs dinner, not just snacks.","price":"$$","priceSource":"The Infatuation / Google Maps","photo":"https://www.bistrotdestournelles.com/i/bistrot-des-tournelles-554913/3/5/8/3/0/5/1/5/1/3/6/9/2/1659108926_161/322ce864025eb6fe3b82efab6e96034b.website.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-bistrot-des-tournelles"},{"id":"marais-food-las-fallafel","name":"L''As du Fallafel","coordinates":[48.8574,2.3591],"description":"L''As du Fallafel is the Rue des Rosiers counter stop that still deserves a save because it solves a different Marais meal: fast, iconic, and better treated as a focused lunch or snack than a full restaurant plan.","price":"$","priceSource":"The Infatuation / Google Maps","photo":"https://upload.wikimedia.org/wikipedia/commons/3/31/L%27As_du_Fallafel%2C_Jewish_Quarter%2C_Paris_2015.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-l-as-du-fallafel"},{"id":"marais-food-parcelles","name":"Parcelles","coordinates":[48.8612,2.3568],"description":"Parcelles is the polished bistro choice for a Marais meal that should feel current but still French. It fits travelers who want a reservation, wine, and careful cooking without leaving the gallery-and-boutique route.","price":"$$$","priceSource":"The Infatuation / Google Maps","photo":"https://www.parcelles-paris.fr/i/parcelles/3/5/4/8/8/6/1/5/1/1/2/5/3/1616675932_336/a6fafd739cd7f9e24bc0afe3dc6f42e2.small_original.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-parcelles"},{"id":"marais-food-enfants-rouges","name":"Marche des Enfants Rouges","coordinates":[48.8627,2.3612],"description":"Marche des Enfants Rouges gives the guide a flexible market format for casual lunches and uneven appetites. Treat it as a grazing stop with neighborhood texture rather than a quiet meal.","price":"$","priceSource":"Eater / Google Maps","photo":"https://res.cloudinary.com/du5jifpgg/image/upload/t_opengraph_image/Surcharge-APIDAE/marche-des-enfants-rouges-tablee.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-marche-des-enfants-rouges"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-bars', 'paris-le-marais-bars', 'Nightlife', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-bars","slug":"paris-le-marais-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Le Marais, Paris","seoDescription":"Best bars in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Cocktails, Pubs, and Old-Quarter Rooms","description":"Le Marais nightlife works because serious cocktail rooms, pub ease, queer-friendly terraces, and late cafes sit close together. This guide keeps the night walkable around the old quarter instead of scattering drinks across Paris.","url":"https://www.google.com/maps/search/Le%20Marais%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-nightlife-bar-nouveau","name":"Bar Nouveau","coordinates":[48.8623,2.3579],"description":"Bar Nouveau is the Art Nouveau cocktail trophy with World 50 Best recognition and a small-room format that rewards early timing. Use it for one focused drink before the night spreads into dinner or another bar.","price":"$$$","priceSource":"World''s 50 Best Bars / Google Maps","photo":"https://barnouveau.fr/wp-content/uploads/2026/04/IMG_2109-2.png","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-bar-nouveau"},{"id":"marais-nightlife-cambridge","name":"The Cambridge Public House","coordinates":[48.8618,2.3632],"description":"The Cambridge Public House bridges pub ease and Paris cocktail precision, making it useful for groups that want serious drinks without whispery formality. It can start or end a wider Marais night.","price":"$$","priceSource":"World''s 50 Best Bars / Time Out","photo":"https://ugc.zenchef.com/3/6/0/6/8/5/1/5/6/7/6/9/4/1760366013_207/a4b7ed07993593cf70eac7ad287d9bbf.website.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-the-cambridge-public-house"},{"id":"marais-nightlife-candelaria","name":"Candelaria","coordinates":[48.8631,2.3615],"description":"Candelaria keeps the Marais bar route playful with a taqueria-front, cocktail-back format that still feels useful near Rue de Saintonge. Save it when the night needs food-adjacent energy and a hidden-room mood.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://images.squarespace-cdn.com/content/v1/601823bdac5fb55d1bfc8913/459898a4-3052-4e7d-995f-8029a76bfa0f/010-CANDELARIA-2022-LOWDEF.jpg?format=1500w","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-candelaria"},{"id":"marais-nightlife-la-perle","name":"La Perle","coordinates":[48.8608,2.3614],"description":"La Perle is the sidewalk-crowd Marais standby for a looser drink between galleries, dinner, and late wandering. Its value is social texture and location, not a perfectly quiet cocktail.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://www.barsparis.com/wp-content/uploads/2012/08/bar-la-perle.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-la-perle"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-parks-and-walks', 'paris-le-marais-parks-and-walks', 'Nature', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-parks-and-walks","slug":"paris-le-marais-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in Le Marais, Paris","seoDescription":"Best parks and walks in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Squares and Quiet Edges Between Streets","description":"Le Marais is dense, so the useful green stops are squares, courtyards, and river edges that break up shopping and museums. This guide gives the old quarter small pauses without leaving the neighborhood route.","url":"https://www.google.com/maps/search/Le%20Marais%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-nature-place-vosges","name":"Place des Vosges","coordinates":[48.8556,2.3655],"description":"Place des Vosges is the Marais garden-square anchor, useful for a pause between arcades, Victor Hugo, Rue des Rosiers, and a bistro meal. It gives the old quarter symmetry and air.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-place-des-vosges"},{"id":"marais-nature-square-temple","name":"Square du Temple - Elie Wiesel","coordinates":[48.8648,2.3605],"description":"Square du Temple - Elie Wiesel is the north Marais green reset near Enfants Rouges and Rue de Bretagne. Use it when the route needs shade and local rhythm away from the busiest lanes.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-du-temple-elie-wiesel"},{"id":"marais-nature-jardin-anne-frank","name":"Jardin Anne Frank","coordinates":[48.861,2.3547],"description":"Jardin Anne Frank is a tucked-away pocket garden that helps the western Marais slow down near museums and shopping streets. It is best as a short decompression stop, not a destination park.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-anne-frank"},{"id":"marais-nature-seine-hotel-ville","name":"Seine Quays by Hotel de Ville","coordinates":[48.8567,2.3522],"description":"The Seine quays by Hotel de Ville pull Le Marais toward the river and give the neighborhood a scenic exit. Use them before crossing to the islands or looping back into the old streets.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-seine-quays-by-hotel-de-ville"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-culture', 'paris-le-marais-culture', 'Culture', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-culture","slug":"paris-le-marais-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Le Marais, Paris","seoDescription":"Best culture in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Mansion Museums and Old-Quarter Memory","description":"Le Marais culture is built from historic houses, civic memory, courtyards, and squares rather than one blockbuster. This guide keeps Picasso, Carnavalet, Victor Hugo, and Hotel de Sully tied to a walkable old-quarter day.","url":"https://www.google.com/maps/search/Le%20Marais%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-culture-picasso","name":"Musee Picasso Paris","coordinates":[48.8599,2.3623],"description":"Inside Le Marais, Musee Picasso Paris adds a real museum block to a route that can otherwise lean too hard on shopping and falafel. The Hotel Sale setting and collection depth make it strong enough to anchor the neighborhood day.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-picasso-paris"},{"id":"marais-culture-carnavalet","name":"Musee Carnavalet","coordinates":[48.8575,2.3629],"description":"Musee Carnavalet is the Paris-history anchor for Le Marais, with free permanent collections and a mansion setting that rewards a slower visit. Use it to add civic context before Place des Vosges or Rue des Rosiers.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-carnavalet"},{"id":"marais-culture-victor-hugo","name":"Maison de Victor Hugo","coordinates":[48.8549,2.3661],"description":"Maison de Victor Hugo turns Place des Vosges into more than a pretty square, giving the route literary rooms and domestic scale. It is best as a compact cultural add-on rather than a full museum day.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-maison-de-victor-hugo"},{"id":"marais-culture-hotel-sully","name":"Hotel de Sully","coordinates":[48.8547,2.3642],"description":"Hotel de Sully gives the Marais one of its best courtyard passages and a clean hinge toward Place des Vosges. Use it when the walk needs architecture and a quieter transition.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-hotel-de-sully"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-hotels-and-hostels', 'paris-le-marais-hotels-and-hostels', 'Stay', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-hotels-and-hostels","slug":"paris-le-marais-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in Le Marais, Paris","seoDescription":"Best hotels and hostels in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Boutique Bases in the Old Quarter","description":"Staying in Le Marais means prioritizing restaurants, bars, galleries, and walkable old-center streets over large-room calm. This guide mixes design hotels and practical budget bases that honestly serve the neighborhood.","url":"https://www.google.com/maps/search/Le%20Marais%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-stay-grand-mazarin","name":"Le Grand Mazarin","coordinates":[48.858,2.3546],"description":"For Le Marais stays, Le Grand Mazarin puts maximalist boutique energy close to Hotel de Ville, galleries, restaurants, and late bars. It suits travelers who want old-center access with design-forward energy.","price":"$$$","priceSource":"Conde Nast Traveler / Vogue","photo":"https://www.legrandmazarin.com/wp-content/uploads/2024/07/hotel-le-grand-mazarin-piscine-hotel.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-le-grand-mazarin"},{"id":"marais-stay-sookie","name":"Hotel Sookie","coordinates":[48.8628,2.3606],"description":"Hotel Sookie is the smaller north Marais base for travelers who want Rue de Bretagne, Enfants Rouges, and gallery streets nearby. It fits a boutique-stay trip better than a palace-service trip.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://cdn.prod.website-files.com/6862bbb7e9136bfb00b4600f/68b98acb3823d6d605a76af6_SOOKIE%20MADEO%20BD%20%C2%A9%20Nicolas%20Anetson-7.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-sookie"},{"id":"marais-stay-jules-jim","name":"Hotel Jules and Jim","coordinates":[48.8632,2.3567],"description":"Hotel Jules and Jim gives the upper Marais a design-hotel option with a courtyard bar and quick access to Arts et Metiers. Use it when nightlife and central movement matter.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://d32rszyoapv4qs.cloudfront.net/cache/img/2590db940b8abcc39ba5ea238be9c982d5d95b65-2590db-1200-627-crop.jpg?q=1731669479","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-jules-and-jim"},{"id":"marais-stay-mije","name":"MIJE Marais","coordinates":[48.8564,2.3615],"description":"MIJE Marais is the budget-friendly historic-house option for travelers who want the old quarter without hotel pricing. It works best for simple rooms, school-group energy, and maximum location value.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://www.mije.com/wp-content/uploads/2025/10/MIJE_Home-Page-header_Desktop_Imges-header_1920x526px_2025_1028.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-mije-marais"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-le-marais-things-to-do', 'paris-le-marais-things-to-do', 'Activities', 'France', 'Paris', 'Le Marais', '{"id":"list-paris-le-marais-things-to-do","slug":"paris-le-marais-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Le Marais, Paris","seoDescription":"Best things to do in Le Marais, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Old Streets, Squares, and Late Stops","description":"Le Marais activities are about density: a mansion museum, a square, food streets, boutiques, and a bar can all fit without transit. This guide turns the neighborhood into a flexible half-day or evening route.","url":"https://www.google.com/maps/search/Le%20Marais%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"Le Marais","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"marais-activity-vosges-picasso","name":"Place des Vosges to Musee Picasso","coordinates":[48.8578,2.364],"description":"Place des Vosges to Musee Picasso is the classic Marais culture walk, pairing a square, mansion museum, and old streets. Use it as the backbone of a daytime route.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-place-des-vosges-to-musee-picasso"},{"id":"marais-activity-rue-rosiers","name":"Rue des Rosiers Food Walk","coordinates":[48.8574,2.3591],"description":"Rue des Rosiers turns a Marais wander into a food-and-history stop with falafel counters, bakeries, and Jewish-quarter context. It is best as a focused lunch or snack block.","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-rue-des-rosiers-food-walk"},{"id":"marais-activity-rue-bretagne","name":"Rue de Bretagne and Enfants Rouges","coordinates":[48.8627,2.3612],"description":"Rue de Bretagne and Enfants Rouges keep the north Marais useful for market grazing, shopping, and cafe stops. Use it when the route needs flexible pacing.","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-rue-de-bretagne-and-enfants-rouges"},{"id":"marais-activity-cocktail-loop","name":"Marais Cocktail Loop","coordinates":[48.862,2.36],"description":"The Marais cocktail loop links Bar Nouveau, Cambridge, Candelaria, and sidewalk cafes without requiring a cross-town night. It works when dinner and drinks should stay close.","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-marais-cocktail-loop"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-restaurants', 'paris-saint-germain-des-pres-restaurants', 'Food', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-restaurants","slug":"paris-saint-germain-des-pres-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Saint-Germain-des-Pres, Paris","seoDescription":"Best restaurants in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Left Bank Tables and Cafe Rituals","description":"Saint-Germain food should not be only cafe mythology. This guide gives the area meal roles: brasserie history, oysters, a modern bistro, a quick sandwich, and one iconic terrace for Left Bank days that need food with context.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-food-lipp","name":"Brasserie Lipp","coordinates":[48.8535,2.3332],"description":"Brasserie Lipp is the Saint-Germain institution for a literary, polished boulevard meal. It is useful when the plan wants old Left Bank atmosphere and classic cooking that can carry lunch or dinner.","price":"$$$","priceSource":"The Infatuation / Google Maps","photo":"https://ugc.zenchef.com/3/4/5/9/5/3/1/5/1/3/7/1/9/1714144479_381/27da576e9c340bdf3ca689ae48b78286.website.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-brasserie-lipp"},{"id":"saint-germain-food-huitrerie-regis","name":"Huitrerie Regis","coordinates":[48.8532,2.3351],"description":"Huitrerie Regis gives Saint-Germain a precise seafood stop with oysters, white wine, and a compact room. Use it when the route needs a clean focused meal rather than a long brasserie sitting.","price":"$$","priceSource":"Eater / Google Maps","photo":"https://huitrerie-regis.com/wp-content/uploads/2020/07/capture-decran-2020-07-07-a-17-03-52.png","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-huitrerie-regis"},{"id":"saint-germain-food-semilla","name":"Semilla","coordinates":[48.8535,2.3374],"description":"Semilla is the modern Left Bank bistro for travelers who want Saint-Germain without only heritage rooms. It fits an evening around galleries, the river, and Odeon.","price":"$$","priceSource":"Eater / Google Maps","photo":"https://cdn.prod.website-files.com/624f207df2b57804135dc63e/667d5c11c3c0c1420724f703_5f61295f-2b15-402f-8cec-a6f017112b97.jpeg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-semilla"},{"id":"saint-germain-food-cafe-flore","name":"Cafe de Flore","coordinates":[48.8542,2.3322],"description":"Cafe de Flore belongs as a context stop, not because it is hidden. Use it when the traveler wants the ritual of Saint-Germain cafe history and understands that the value is room and address.","price":"$$","priceSource":"Conde Nast Traveler / Google Maps","photo":"https://cafedeflore.fr/wp-content/uploads/2022/07/cdf_hero1.jpeg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-cafe-de-flore"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-bars', 'paris-saint-germain-des-pres-bars', 'Nightlife', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-bars","slug":"paris-saint-germain-des-pres-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Saint-Germain-des-Pres, Paris","seoDescription":"Best bars in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Left Bank Cocktails, Jazz, and Hotel Bars","description":"Saint-Germain nightlife is best when it stays elegant but not sleepy: cocktail rooms, hotel bars, market-street terraces, and cellar energy. This guide keeps the Left Bank evening close to dinner and river walks.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-nightlife-prescription","name":"Prescription Cocktail Club","coordinates":[48.8538,2.3372],"description":"Prescription Cocktail Club gives Saint-Germain a proper cocktail-room option near Odeon and Rue Mazarine. It is best when the night wants low light, careful drinks, and a short walk from dinner.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://cdn.prod.website-files.com/625f3ce29cfd1cc533cebdf6/62609641f22bd813a6eeb801_og-image.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-prescription-cocktail-club"},{"id":"saint-germain-nightlife-josephine","name":"Bar Josephine","coordinates":[48.8517,2.327],"description":"Bar Josephine at Hotel Lutetia brings grand Left Bank hotel energy with live-music polish and a room that can carry the whole evening. Use it for a composed nightcap or a more dressed-up start.","price":"$$$","priceSource":"Official hotel site / Google Maps","photo":"https://media.ffycdn.net/eu/mandarin-oriental-hotel-group/nsZ8J29W3zvRCSVUKdTY.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-bar-josephine"},{"id":"saint-germain-nightlife-bar-marche","name":"Le Bar du Marche","coordinates":[48.8532,2.3362],"description":"Le Bar du Marche is the casual terrace choice near Rue de Buci, useful when the group wants a simple drink in the middle of the Saint-Germain evening flow. It is more social hinge than destination cocktail bar.","price":"$$","priceSource":"Google Maps / local nightlife guides","photo":"https://upload.wikimedia.org/wikipedia/commons/9/96/Rue_de_Seine%2C_75006_Paris_2012.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-bar-du-marche"},{"id":"saint-germain-nightlife-castor-club","name":"Castor Club","coordinates":[48.8539,2.3392],"description":"Castor Club gives the Left Bank a small, polished cocktail stop close to the river and Odeon. Save it for a focused drink when the night should stay intimate and walkable.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://res.cloudinary.com/the-infatuation/image/upload/f_auto/q_auto/v1714688747/TTownsend_photo3_ucrfbj.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-castor-club"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-parks-and-walks', 'paris-saint-germain-des-pres-parks-and-walks', 'Nature', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-parks-and-walks","slug":"paris-saint-germain-des-pres-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in Saint-Germain-des-Pres, Paris","seoDescription":"Best parks and walks in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Luxembourg Chairs and River Walks","description":"Saint-Germain nature is mostly elegant pause space: Luxembourg chairs, small squares, and Seine edges. This guide keeps the Left Bank route breathable between galleries, cafes, Orsay, and dinner.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-nature-luxembourg","name":"Jardin du Luxembourg","coordinates":[48.8462,2.3372],"description":"From Saint-Germain, Jardin du Luxembourg is the natural reset before the route drifts toward the Latin Quarter or another museum block. Chairs, fountains, and palace views make it a practical pause rather than a detour.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-du-luxembourg"},{"id":"saint-germain-nature-laurent-prache","name":"Square Laurent-Prache","coordinates":[48.8543,2.3342],"description":"Square Laurent-Prache is the small garden beside the church, useful when the boulevard needs a quiet minute. It works as a compact pause between cafes, shops, and the Delacroix museum.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-laurent-prache"},{"id":"saint-germain-nature-gabriel-pierne","name":"Square Gabriel-Pierne","coordinates":[48.8548,2.3375],"description":"Square Gabriel-Pierne gives Rue de Seine and the galleries a leafy pocket with benches and a quieter rhythm. Use it when the Left Bank walk needs shade without turning into a park visit.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-gabriel-pierne"},{"id":"saint-germain-nature-quai-malaquais","name":"Quai Malaquais Seine Walk","coordinates":[48.858,2.335],"description":"Quai Malaquais pulls Saint-Germain to the river, with views toward the Louvre and easy movement to Pont des Arts. It is the best reset between galleries, Orsay, and a central dinner.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-quai-malaquais-seine-walk"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-culture', 'paris-saint-germain-des-pres-culture', 'Culture', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-culture","slug":"paris-saint-germain-des-pres-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Saint-Germain-des-Pres, Paris","seoDescription":"Best culture in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Abbey, Galleries, and Left Bank Rooms","description":"Saint-Germain culture works at a smaller scale than the Louvre: church history, artist rooms, institutions, galleries, and the river. This guide keeps the neighborhood intellectual without making it feel like homework.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-culture-eglise","name":"Eglise Saint-Germain-des-Pres","coordinates":[48.8539,2.3346],"description":"Eglise Saint-Germain-des-Pres anchors the neighborhood with early-medieval depth and a direct link to the Left Bank''s name. Use it as the compact cultural start before cafes or galleries.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-eglise-saint-germain-des-pres"},{"id":"saint-germain-culture-delacroix","name":"Musee national Eugene-Delacroix","coordinates":[48.8541,2.3356],"description":"Musee national Eugene-Delacroix is a small artist-house museum that rewards a slower Saint-Germain day. It pairs naturally with the church, Rue de Furstenberg, and a cafe stop.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-national-eugene-delacroix"},{"id":"saint-germain-culture-monnaie","name":"Monnaie de Paris","coordinates":[48.8567,2.3391],"description":"Monnaie de Paris gives the Seine edge an institution with exhibitions, craft history, and a strong courtyard setting. Use it when the neighborhood needs a cultural stop beyond literary cafes.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-monnaie-de-paris"},{"id":"saint-germain-culture-institut","name":"Institut de France","coordinates":[48.8572,2.3376],"description":"Institut de France is a landmark exterior and riverfront orientation point across from the Louvre. It works as a cultural marker on a gallery-and-quay walk rather than a long visit.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-institut-de-france"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-hotels-and-hostels', 'paris-saint-germain-des-pres-hotels-and-hostels', 'Stay', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-hotels-and-hostels","slug":"paris-saint-germain-des-pres-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in Saint-Germain-des-Pres, Paris","seoDescription":"Best hotels and hostels in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Grand Left Bank and Quiet Boutique Bases","description":"Saint-Germain stays are for travelers who want cafe mornings, galleries, Luxembourg access, and calm returns after museum days. This guide balances palace heritage with smaller hotels close to the Left Bank route.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-stay-lutetia","name":"Hotel Lutetia","coordinates":[48.8517,2.327],"description":"In Saint-Germain, Hotel Lutetia is the grand hotel choice for Orsay, Luxembourg, polished cafe routes, and Left Bank calm. Choose it when heritage matters more than immediate Marais nightlife.","price":"$$$","priceSource":"Conde Nast Traveler / The Times","photo":"https://media.ffycdn.net/eu/mandarin-oriental-hotel-group/nsZ8J29W3zvRCSVUKdTY.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-lutetia"},{"id":"saint-germain-stay-relais-christine","name":"Relais Christine","coordinates":[48.8541,2.3403],"description":"Relais Christine gives Saint-Germain a tucked-away luxury base near the river and Odeon. It fits travelers who want quiet, romance, and historic-street access rather than lobby scene.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://www.relais-christine.com/_novaimg/4915897-1568694_0_0_4800_3023_2000_1260-1600.webp","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-relais-christine"},{"id":"saint-germain-stay-aubusson","name":"Hotel d''Aubusson","coordinates":[48.8545,2.3396],"description":"Hotel d''Aubusson is a polished Left Bank hotel with jazz-bar energy and easy access to Rue de Buci, the Seine, and galleries. It works when the stay should support both culture and evenings.","price":"$$$","priceSource":"Google Travel / Tripadvisor","photo":"https://api.pulse-cdn.com/api/v1/resize/uploads/175585-hotel-daubusson/7ad7838c-9bb5-48e6-9d34-fb729882af50.jpg-crop-1200-627-90-webp","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-d-aubusson"},{"id":"saint-germain-stay-madison","name":"Madison Hotel","coordinates":[48.8534,2.3338],"description":"Madison Hotel gives the boulevard a practical boutique base beside the church and classic cafes. Use it when location, metro access, and Saint-Germain identity matter more than resort amenities.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://cdn.prod.website-files.com/698a0b7e7e2005d6daeaa106/69a9877d0825f4a1ef17b909_1b7a495f330d533899299a529fcae740_hotel-madison.avif","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-madison-hotel"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-saint-germain-des-pres-things-to-do', 'paris-saint-germain-des-pres-things-to-do', 'Activities', 'France', 'Paris', 'Saint-Germain-des-Pres', '{"id":"list-paris-saint-germain-des-pres-things-to-do","slug":"paris-saint-germain-des-pres-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Saint-Germain-des-Pres, Paris","seoDescription":"Best things to do in Saint-Germain-des-Pres, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Cafe Rituals, Galleries, and Garden Time","description":"Saint-Germain activities are best built as a slow Left Bank sequence: coffee, church, galleries, garden, river, and dinner. This guide keeps the neighborhood polished without turning it into a postcard cafe crawl.","url":"https://www.google.com/maps/search/Saint-Germain-des-Pres%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"Saint-Germain-des-Pres","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"saint-germain-activity-cafe-abbey","name":"Cafe and Abbey Loop","coordinates":[48.854,2.334],"description":"The cafe and abbey loop links Cafe de Flore, Brasserie Lipp, and Eglise Saint-Germain-des-Pres into one compact Left Bank ritual. Use it early, before the boulevard gets too crowded.","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-cafe-and-abbey-loop"},{"id":"saint-germain-activity-rue-seine","name":"Rue de Seine Gallery Walk","coordinates":[48.8547,2.3367],"description":"Rue de Seine gives Saint-Germain a browsable gallery spine between the church and river. It works when the day needs looking, wandering, and small cultural stops without another ticket.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-rue-de-seine-gallery-walk"},{"id":"saint-germain-activity-luxembourg-odeon","name":"Luxembourg to Odeon","coordinates":[48.8488,2.339],"description":"Luxembourg to Odeon is the soft walking block that connects garden chairs, bookshops, cinemas, and dinner streets. Use it to keep the Left Bank day relaxed.","photo":"https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-luxembourg-to-odeon"},{"id":"saint-germain-activity-orsay-bridge","name":"Orsay Bridge Walk","coordinates":[48.8585,2.3295],"description":"The Orsay bridge walk connects Saint-Germain to the museum side through the Seine instead of the metro. It is a useful activity when art, views, and dinner need to stay aligned.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-orsay-bridge-walk"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-restaurants', 'paris-latin-quarter-restaurants', 'Food', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-restaurants","slug":"paris-latin-quarter-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Latin Quarter, Paris","seoDescription":"Best restaurants in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Student Streets and Serious Tables","description":"Latin Quarter food should cover more than tourist menus: bakeries, historic dining rooms, student-value plates, and one serious river-edge meal. This guide keeps meals tied to the Pantheon, Mouffetard, Cluny, and the Seine.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-food-coupe-chou","name":"Le Coupe-Chou","coordinates":[48.8485,2.3483],"description":"Le Coupe-Chou gives the Latin Quarter a candlelit old-house meal near the Sorbonne and Pantheon. Use it when the route wants atmosphere and a slower dinner without leaving the university streets.","price":"$$","priceSource":"Google Maps / local dining guides","photo":"https://cdn.prod.website-files.com/5e6a2ea265f9f1264938a720/602417fb3fcbd5628e841ad3_lecoupechou45-1000-520.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-le-coupe-chou"},{"id":"latin-food-bouillon-racine","name":"Bouillon Racine","coordinates":[48.849,2.341],"description":"Bouillon Racine is the Art Nouveau dining-room choice near Odeon and Cluny, useful when the day needs a historic room at a more accessible format. It is best for groups that want setting and classic comfort.","price":"$$","priceSource":"Google Maps / local dining guides","photo":"https://ugc.zenchef.com/1/3/2/1/5/1/9/7/7/2/1749814348_332/c5e75c355c4e9d46c7f10148ed39967f.website.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-bouillon-racine"},{"id":"latin-food-maison-isabelle","name":"La Maison d''Isabelle","coordinates":[48.8498,2.3486],"description":"La Maison d''Isabelle is the croissant and bakery stop that makes a Latin Quarter morning feel planned. Use it before the Pantheon, Mouffetard, or a museum block when breakfast should be quick and good.","price":"$","priceSource":"Google Maps / Paris bakery guides","photo":"https://assets.gaultmillau.com/assets/05bbfae9-77c0-4219-b263-e978db260669?width=666&height=444&fit=cover&format=webp","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-la-maison-d-isabelle"},{"id":"latin-food-tour-argent","name":"La Tour d''Argent","coordinates":[48.8499,2.3544],"description":"La Tour d''Argent is the formal river-edge splurge for travelers who want old Paris ceremony and a view-backed meal. It belongs as a deliberate booking, not a casual neighborhood dinner.","price":"$$$","priceSource":"MICHELIN Guide / Google Maps","photo":"https://tourdargent.com/wp-content/uploads/2023/10/HomePage_Transition-1920x1146.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-la-tour-d-argent"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-bars', 'paris-latin-quarter-bars', 'Nightlife', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-bars","slug":"paris-latin-quarter-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Latin Quarter, Paris","seoDescription":"Best bars in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Cellars, Student Bars, and Late Jazz","description":"Latin Quarter nights work when the student energy and old-cellar culture are used deliberately. This guide gives the neighborhood jazz, pubs, and casual bars that fit after bookshops, dinner, or a Pantheon day.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-nightlife-huchette","name":"Le Caveau de la Huchette","coordinates":[48.8525,2.3468],"description":"Le Caveau de la Huchette is the Latin Quarter jazz-cellar anchor, useful when nightlife should be music and dancing rather than another cocktail list. Check the program before building the night around it.","price":"$$","priceSource":"Official venue site / Google Maps","photo":"https://www.caveaudelahuchette.fr/1/images/12084_0_3348528_100831.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-caveau-de-la-huchette"},{"id":"latin-nightlife-piano-vache","name":"Le Piano Vache","coordinates":[48.8503,2.3488],"description":"Le Piano Vache gives the area a student-bar institution with posters, inexpensive drinks, and a looser mood near the Sorbonne. Use it when the night should stay casual and local-feeling.","price":"$","priceSource":"Google Maps / local nightlife guides","photo":"https://www.lepianovache.fr/wp-content/uploads/2019/02/cropped-wolfgang-hasselmann-1266795-unsplash-1.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-piano-vache"},{"id":"latin-nightlife-teddys","name":"Teddy''s Bar","coordinates":[48.8473,2.3443],"description":"Teddy''s Bar is a compact cocktail and beer stop near Mouffetard, useful for a low-pressure drink after dinner. It works best as part of a small Latin Quarter bar sequence.","price":"$$","priceSource":"Google Maps / local nightlife guides","photo":"https://storage.googleapis.com/schlouk-map/cache/gallery/uploads/images/places/teddys-bar-620cf617b686b5.56325506.jpeg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-teddy-s-bar"},{"id":"latin-nightlife-requin","name":"Le Requin Chagrin","coordinates":[48.8465,2.3478],"description":"Le Requin Chagrin is the pub-style stop near the Pantheon and student streets, good for groups that want easy drinks without a reservation ritual. Save it for a casual second stop.","price":"$","priceSource":"Google Maps / local nightlife guides","photo":"https://upload.wikimedia.org/wikipedia/commons/5/53/CF1505_Paris_5e_place_Contrescarpe_Requin_Chagrin_rwk.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-requin-chagrin"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-parks-and-walks', 'paris-latin-quarter-parks-and-walks', 'Nature', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-parks-and-walks","slug":"paris-latin-quarter-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in Latin Quarter, Paris","seoDescription":"Best parks and walks in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Gardens, Arenas, and River Breathing Room","description":"The Latin Quarter has real green relief if the route steps off the lecture-hall streets. This guide links Luxembourg, Jardin des Plantes, Arenes de Lutece, and the Seine for pauses between culture and food.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-nature-luxembourg","name":"Jardin du Luxembourg","coordinates":[48.8462,2.3372],"description":"Jardin du Luxembourg is the western green anchor for Latin Quarter days, especially before or after the Pantheon and Sorbonne. Chairs, fountains, and paths make it the easiest long pause.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-du-luxembourg"},{"id":"latin-nature-jardin-plantes","name":"Jardin des Plantes","coordinates":[48.8439,2.3599],"description":"Jardin des Plantes stretches the Latin Quarter east toward natural history, garden paths, and family-friendly museum time. It is best when the day needs greenery and a quieter rhythm.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-des-plantes"},{"id":"latin-nature-arenes","name":"Arenes de Lutece","coordinates":[48.8451,2.3522],"description":"Arenes de Lutece gives the neighborhood a Roman open-air pocket tucked behind ordinary streets. Use it as a short historical and green stop between Mouffetard and Jardin des Plantes.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-arenes-de-lutece"},{"id":"latin-nature-seine-bookstalls","name":"Seine Bookstalls and Quays","coordinates":[48.8527,2.347],"description":"The Seine bookstalls and quays are the Latin Quarter''s river reset, linking Shakespeare and Company, Notre-Dame views, and slow browsing. It is the easiest way to add air to a bookish route.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-seine-bookstalls-and-quays"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-culture', 'paris-latin-quarter-culture', 'Culture', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-culture","slug":"paris-latin-quarter-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Latin Quarter, Paris","seoDescription":"Best culture in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Books, Domes, and Medieval Rooms","description":"The Latin Quarter deserves its own cultural map because university streets, bookshops, medieval rooms, civic monuments, and gardens sit close enough to walk. Use this for history without turning the day into lectures and plaques.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-culture-pantheon","name":"Pantheon","coordinates":[48.8462,2.346],"description":"The Pantheon is the Latin Quarter''s civic-history anchor, connecting republican memory, architecture, and the Sorbonne-side street grid. It is best paired with Luxembourg or Cluny rather than rushed as a dome photo.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-pantheon"},{"id":"latin-culture-cluny","name":"Musee de Cluny","coordinates":[48.8506,2.3431],"description":"Musee de Cluny is the medieval counterweight to the big art museums, with tapestries, Roman bath remains, and a scale that suits a slower Left Bank day. It is useful when the group needs culture without Louvre sprawl.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-de-cluny"},{"id":"latin-culture-shakespeare","name":"Shakespeare and Company","coordinates":[48.8526,2.3471],"description":"Shakespeare and Company is touristy for a reason, but it still gives the Latin Quarter its English-language literary stop near Notre-Dame and the Seine. Save it for a short browse and river walk.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-shakespeare-and-company"},{"id":"latin-culture-sorbonne","name":"Place de la Sorbonne","coordinates":[48.8487,2.3437],"description":"Place de la Sorbonne turns the area''s academic identity into a simple walking anchor. It works as connective tissue between the Pantheon, cafes, bookshops, and Luxembourg.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-place-de-la-sorbonne"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-hotels-and-hostels', 'paris-latin-quarter-hotels-and-hostels', 'Stay', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-hotels-and-hostels","slug":"paris-latin-quarter-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in Latin Quarter, Paris","seoDescription":"Best hotels and hostels in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Bookish Bases Near the Pantheon","description":"Latin Quarter stays work for travelers who want student streets, bookshops, gardens, and easy RER or metro access. This guide balances boutique hotels, older quiet rooms, and one budget base that honestly serves the area.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-stay-dames-pantheon","name":"Hotel Les Dames du Pantheon","coordinates":[48.846,2.3459],"description":"Hotel Les Dames du Pantheon is the location-first boutique stay with Pantheon views and direct access to the Sorbonne side. It fits travelers who want literary Left Bank mood and short walks.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://moonback-hotelbeds.b-cdn.net/21/213073/213073a_hb_ro_003.jpg?aspect_ratio=1200:628&width=1200&height=628","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-les-dames-du-pantheon"},{"id":"latin-stay-grandes-ecoles","name":"Hotel des Grandes Ecoles","coordinates":[48.8434,2.3509],"description":"Hotel des Grandes Ecoles gives the Latin Quarter a courtyard-garden hotel near Mouffetard. Use it when calm, charm, and neighborhood feel matter more than large luxury services.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://afar.brightspotcdn.com/dims4/default/71a678c/2147483647/strip/true/crop/1150x575+0+72/resize/1440x720!/quality/90/?url=https%3A%2F%2Fk3-prod-afar-media.s3.us-west-2.amazonaws.com%2Fbrightspot%2F92%2F49%2F3f50821ecdb57159ea09957abf9a%2Foriginal-a7ea05ff22395157eed13e6709f449ae.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-des-grandes-ecoles"},{"id":"latin-stay-monte-cristo","name":"Hotel Monte Cristo","coordinates":[48.8377,2.3523],"description":"Hotel Monte Cristo is the southern Latin Quarter boutique base with a more styled, tucked-away mood. It works for travelers who want access to Mouffetard, Jardin des Plantes, and quieter nights.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://www.hotelmontecristoparis.com/cache/img/6066525bbb917692f4a819383d3dca1b68e553e6-606652-1200-627-crop.jpg?q=1714492043&q=1777540737","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-monte-cristo"},{"id":"latin-stay-young-happy","name":"Young and Happy Latin Quarter","coordinates":[48.8446,2.3507],"description":"Young and Happy Latin Quarter is the budget hostel pick for travelers who want Mouffetard, student bars, and simple access to the Pantheon area. It is strongest for social, low-cost stays.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://www.youngandhappy.fr/wp-content/uploads/2024/01/dortoir-sdb-6-1024x682.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-young-and-happy-latin-quarter"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-latin-quarter-things-to-do', 'paris-latin-quarter-things-to-do', 'Activities', 'France', 'Paris', 'Latin Quarter', '{"id":"list-paris-latin-quarter-things-to-do","slug":"paris-latin-quarter-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Latin Quarter, Paris","seoDescription":"Best things to do in Latin Quarter, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"A Bookish Left Bank Day","description":"Latin Quarter activities should move between books, civic history, gardens, and student streets. This guide turns the neighborhood into a walkable day with culture, browsing, food, and river edges.","url":"https://www.google.com/maps/search/Latin%20Quarter%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"Latin Quarter","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"latin-activity-pantheon-cluny","name":"Pantheon and Cluny Route","coordinates":[48.8484,2.3447],"description":"The Pantheon and Cluny route gives the Latin Quarter its civic and medieval backbone in one compact walk. Use it when the day needs two strong cultural anchors without cross-town travel.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-pantheon-and-cluny-route"},{"id":"latin-activity-bookshops-seine","name":"Bookshops and the Seine","coordinates":[48.8526,2.3471],"description":"Bookshops and the Seine link Shakespeare and Company, bouquinistes, Notre-Dame views, and river walking. It is the classic short activity when the neighborhood needs romance and browsing.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-bookshops-and-the-seine"},{"id":"latin-activity-jardin-plantes","name":"Jardin des Plantes Afternoon","coordinates":[48.8439,2.3599],"description":"A Jardin des Plantes afternoon adds gardens, natural-history museums, and family-friendly pacing to the Latin Quarter. It works especially well after dense historic streets.","photo":"https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-des-plantes-afternoon"},{"id":"latin-activity-mouffetard","name":"Rue Mouffetard Food Walk","coordinates":[48.8427,2.3494],"description":"Rue Mouffetard gives the area a market-street activity with bakeries, cheese shops, cafes, and casual dinner options. Use it when the day needs food texture rather than another ticket.","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-rue-mouffetard-food-walk"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-restaurants', 'paris-montmartre-restaurants', 'Food', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-restaurants","slug":"paris-montmartre-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Montmartre, Paris","seoDescription":"Best restaurants in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Hill Meals Beyond the View","description":"Montmartre food is strongest when the meal has a purpose: a poultry room, a tiny bistro, a brunch stop, or a village-street dinner. This guide keeps the hill from becoming only crepes, views, and souvenir lanes.","url":"https://www.google.com/maps/search/Montmartre%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-food-coq-fils","name":"Le Coq and Fils","coordinates":[48.887,2.3383],"description":"Le Coq and Fils gives Montmartre a poultry-focused destination meal near the upper hill without leaning on postcard atmosphere alone. Use it for a planned lunch or dinner after the museum lanes.","price":"$$$","priceSource":"MICHELIN Guide / Google Maps","photo":"https://lecoq-fils.com/wp-content/uploads/2022/12/actualitepreco.png","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-le-coq-and-fils"},{"id":"montmartre-food-boite-lettres","name":"La Boite aux Lettres","coordinates":[48.8878,2.3356],"description":"La Boite aux Lettres is the small bistro pick for travelers who want a neighborhood dinner near Lamarck-Caulaincourt. It works when the hill needs warmth, wine, and a room that feels local.","price":"$$","priceSource":"Google Maps / Paris dining guides","photo":"https://laboiteauxlettres.com/img/salle.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-la-boite-aux-lettres"},{"id":"montmartre-food-hardware","name":"Hardware Societe","coordinates":[48.886,2.3438],"description":"Hardware Societe is the brunch and coffee stop that makes a Sacre-Coeur morning more useful. It is best before the crowds thicken or after an early hill walk.","price":"$$","priceSource":"Google Maps / local dining guides","photo":"https://images.squarespace-cdn.com/content/v1/6202a63f39310b632ffdebe9/58763b99-2662-4126-9676-6b78139ba27c/HardwareSociety_July19Menu_LowRes_5544.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-hardware-societe"},{"id":"montmartre-food-poulbot","name":"Le Poulbot","coordinates":[48.8866,2.3404],"description":"Le Poulbot gives the central hill a compact French meal close to Place du Tertre without fully surrendering to the tourist strip. Use it when staying on the summit matters.","price":"$$","priceSource":"Google Maps / local dining guides","photo":"https://cty.hju.mybluehost.me/wp-content/uploads/2017/11/GaminPauvrede-Paris_Francisque_Poulbot8plus.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-le-poulbot"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-bars', 'paris-montmartre-bars', 'Nightlife', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-bars","slug":"paris-montmartre-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Montmartre, Paris","seoDescription":"Best bars in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Hilltop Nightcaps and Old Cabaret Energy","description":"Montmartre nights work when they lean into the hill: rooftop views, old cabaret rooms, intimate hotel bars, and lower-hill dives. This guide keeps after-dark plans tied to the neighborhood''s slope and mood.","url":"https://www.google.com/maps/search/Montmartre%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-nightlife-terrass","name":"Terrass Hotel Rooftop","coordinates":[48.8852,2.3326],"description":"Terrass Hotel Rooftop gives Montmartre a view-led drink without climbing back to the basilica steps. Use it for sunset, an early aperitif, or a calmer nightcap on the west side of the hill.","price":"$$$","priceSource":"Official hotel site / Google Maps","photo":"https://cdn.prod.website-files.com/62693a7ecfa12581d78e342f/62d81e5754d58251dcd6e467_Opengraph%20Terrass%20Hotel%20Montmartre%20Paris.png","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-terrass-hotel-rooftop"},{"id":"montmartre-nightlife-lapin-agile","name":"Au Lapin Agile","coordinates":[48.8888,2.3401],"description":"Au Lapin Agile is the historic cabaret stop that keeps Montmartre connected to song, performance, and artist lore. Check the schedule and treat it as a planned show, not a drop-in bar.","price":"$$","priceSource":"Official venue site / Google Maps","photo":"https://i0.wp.com/au-lapin-agile.com/wp-content/uploads/2022/11/cabaret_accueil_nuit_01.jpeg?w=1914&ssl=1","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-au-lapin-agile"},{"id":"montmartre-nightlife-tres-particulier","name":"Le Tres Particulier","coordinates":[48.8882,2.3339],"description":"Le Tres Particulier is the hidden cocktail bar inside Hotel Particulier Montmartre, useful when the night wants garden secrecy and a more refined hilltop mood. Book or confirm access before relying on it.","price":"$$$","priceSource":"Official hotel site / Google Maps","photo":"https://1e64.net/lw-hpm-48dbc2/uploads/logo-facade-hotel-particulier-montmarte-yeZp.webp","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-tres-particulier"},{"id":"montmartre-nightlife-marlusse","name":"Marlusse et Lapin","coordinates":[48.8842,2.3364],"description":"Marlusse et Lapin is the lower-hill bar for a looser, playful drink near Abbesses. It works when Montmartre should end social and casual rather than polished.","price":"$$","priceSource":"Google Maps / local nightlife guides","photo":"https://www.barsparis.com/wp-content/uploads/2012/02/bar-marlusse-et-lapin-2.png","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-marlusse-et-lapin"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-parks-and-walks', 'paris-montmartre-parks-and-walks', 'Nature', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-parks-and-walks","slug":"paris-montmartre-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in Montmartre, Paris","seoDescription":"Best parks and walks in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Steps, Slopes, and Quiet Hill Corners","description":"Montmartre''s outdoor value is slope, view, and small green pockets rather than big parks. This guide links the basilica steps, squares, cemetery paths, and quieter hill corners into a route with real pauses.","url":"https://www.google.com/maps/search/Montmartre%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-nature-sacre-steps","name":"Sacre-Coeur Steps","coordinates":[48.8867,2.3431],"description":"The Sacre-Coeur steps are the obvious view point, but they work best early or late when the hill has room to breathe. Use them as a timed outdoor stop, not an all-day hangout.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-sacre-coeur-steps"},{"id":"montmartre-nature-louise-michel","name":"Square Louise Michel","coordinates":[48.8846,2.3443],"description":"Square Louise Michel gives the climb to Sacre-Coeur a garden frame, with switchback paths, lawns, and changing city views. It is useful when the route needs a slower ascent.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-louise-michel"},{"id":"montmartre-nature-suzanne-buisson","name":"Square Suzanne Buisson","coordinates":[48.8886,2.3369],"description":"Square Suzanne Buisson is a quieter green pocket on the back side of the hill, away from the busiest summit lanes. Use it between Lamarck-Caulaincourt and the old mills.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-suzanne-buisson"},{"id":"montmartre-nature-cemetery","name":"Cimetiere de Montmartre","coordinates":[48.8875,2.3306],"description":"Cimetiere de Montmartre adds a leafy, reflective walk below the hill and works as a calmer counterpoint to Sacre-Coeur crowds. It is best for a slow route toward Pigalle or Rue Caulaincourt.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-cimetiere-de-montmartre"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-culture', 'paris-montmartre-culture', 'Culture', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-culture","slug":"paris-montmartre-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Montmartre, Paris","seoDescription":"Best culture in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Hilltop Views Without the Rush","description":"Montmartre needs a guide because the famous stops can overwhelm the village texture. This route keeps Sacre-Coeur, artist history, old mills, and quieter lanes together without turning the hill into a photo queue.","url":"https://www.google.com/maps/search/Montmartre%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-culture-sacre-coeur","name":"Basilique du Sacre-Coeur","coordinates":[48.8867,2.3431],"description":"Sacre-Coeur is the hilltop anchor, but the best visit treats the basilica, dome, steps, and view as one timed block. Go early or late, then leave room for side streets.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-basilique-du-sacre-coeur"},{"id":"montmartre-culture-musee-montmartre","name":"Musee de Montmartre","coordinates":[48.8872,2.3408],"description":"Musee de Montmartre gives the hill context beyond the basilica, with artist history, gardens, and a calmer pace near the busiest lanes. It is useful when the route needs texture instead of another viewpoint.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-de-montmartre"},{"id":"montmartre-culture-place-tertre","name":"Place du Tertre","coordinates":[48.8865,2.3407],"description":"Place du Tertre is crowded and commercial, but it still explains the neighborhood''s artist-brand mythology. Pass through briefly, then use it as a hinge toward quieter lanes.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-place-du-tertre"},{"id":"montmartre-culture-moulin-galette","name":"Moulin de la Galette","coordinates":[48.8873,2.3367],"description":"Moulin de la Galette helps turn Montmartre from postcard into neighborhood history: mills, artists, and winding streets. Use it as a walking marker between Lamarck-Caulaincourt, Abbesses, and the summit.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-moulin-de-la-galette"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-hotels-and-hostels', 'paris-montmartre-hotels-and-hostels', 'Stay', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-hotels-and-hostels","slug":"paris-montmartre-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in Montmartre, Paris","seoDescription":"Best hotels and hostels in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Hilltop Hotels and Social Budget Bases","description":"Montmartre stays are for travelers who want village streets, north-side evenings, and views more than central monument access. This guide balances rooftop hotels, small boutiques, and hostel bases near the hill.","url":"https://www.google.com/maps/search/Montmartre%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-stay-terrass","name":"Terrass Hotel","coordinates":[48.8852,2.3326],"description":"Terrass Hotel is the view-led Montmartre stay with rooftop drinks and easy access to Rue Caulaincourt and Abbesses. Use it when the hill should shape mornings and evenings.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://cdn.prod.website-files.com/62693a7ecfa12581d78e342f/62d81e5754d58251dcd6e467_Opengraph%20Terrass%20Hotel%20Montmartre%20Paris.png","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-terrass-hotel"},{"id":"montmartre-stay-arts","name":"Hotel des Arts Montmartre","coordinates":[48.8853,2.3348],"description":"Hotel des Arts Montmartre is a smaller neighborhood hotel close to Abbesses, restaurants, and hill walks. It fits travelers who want Montmartre charm without a big hotel scene.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://d1txkfjbeeh9pc.cloudfront.net/cache/img/8af589222e4bd0bca6a45a7d26470d3c4bcf0db0-8af589-1200-627-crop.jpg?q=1713865147","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-des-arts-montmartre"},{"id":"montmartre-stay-village","name":"Le Village Montmartre","coordinates":[48.8842,2.3446],"description":"Le Village Montmartre is the hostel base near Anvers and Sacre-Coeur for budget travelers who want the hill within minutes. It works for simple dorms or privates with social energy.","price":"$","priceSource":"Hostelworld / HostelsClub","photo":"https://www.villagehostel.fr/wp-content/uploads/2017/10/DBL-Large-1024x683.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-le-village-montmartre"},{"id":"montmartre-stay-momart","name":"Mom''Art Hotel","coordinates":[48.8846,2.3432],"description":"Mom''Art Hotel gives the lower hill a compact boutique option near Anvers and Sacre-Coeur. Use it when convenience to the climb matters more than a quiet residential pocket.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://www.hotelmomart.com/wp-content/uploads/sites/544/2023/05/FR-Paris-Hotel-Mom-Art-Patio-3728-1-2200x1200.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-mom-art-hotel"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-montmartre-things-to-do', 'paris-montmartre-things-to-do', 'Activities', 'France', 'Paris', 'Montmartre', '{"id":"list-paris-montmartre-things-to-do","slug":"paris-montmartre-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Montmartre, Paris","seoDescription":"Best things to do in Montmartre, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"A Hill Walk With Timing","description":"Montmartre activities need timing because the famous lanes crowd quickly. This guide builds the hill as a route: basilica, museum, old streets, lower-hill cafes, and an evening that does not depend on one viewpoint.","url":"https://www.google.com/maps/search/Montmartre%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"Montmartre","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"montmartre-activity-sacre-sunrise","name":"Sacre-Coeur Early or Late","coordinates":[48.8867,2.3431],"description":"Sacre-Coeur early or late is the best way to make the hill feel spacious rather than hectic. Use the timing to pair the basilica, steps, and view with quieter lanes.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-sacre-coeur-early-or-late"},{"id":"montmartre-activity-artist-lanes","name":"Musee de Montmartre and Artist Lanes","coordinates":[48.8872,2.3408],"description":"Musee de Montmartre and the artist lanes give the neighborhood context beyond Place du Tertre. It is a useful activity block for travelers who want history with the walk.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-de-montmartre-and-artist-lanes"},{"id":"montmartre-activity-abbesses-lamarck","name":"Abbesses to Lamarck-Caulaincourt","coordinates":[48.886,2.3365],"description":"Abbesses to Lamarck-Caulaincourt is the calmer slope walk through cafes, shops, and back-of-hill streets. Use it when the route needs Montmartre texture without staying on the summit.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-abbesses-to-lamarck-caulaincourt"},{"id":"montmartre-activity-cabaret-night","name":"Cabaret and Hill Night","coordinates":[48.8888,2.3401],"description":"A cabaret and hill night uses Au Lapin Agile, rooftop drinks, or lower-hill bars to keep Montmartre after dark. It works when the evening is planned around a show or view.","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-cabaret-and-hill-night"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-restaurants', 'paris-canal-saint-martin-restaurants', 'Food', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-restaurants","slug":"paris-canal-saint-martin-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Canal Saint-Martin, Paris","seoDescription":"Best restaurants in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Bakery Mornings and Canal Tables","description":"Canal Saint-Martin food is best when it follows the water: bakery starts, brunch queues, rotating kitchens, and terrace meals. This guide keeps the meal plan walkable along the locks and north-south canal spine.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-food-du-pain","name":"Du Pain et des Idees","coordinates":[48.8719,2.3622],"description":"Du Pain et des Idees is the bakery stop that makes canal mornings feel intentional. Use it for pastries and bread before the locks, Republique, or a north Marais route.","price":"$","priceSource":"Eater / Google Maps","photo":"https://cdn.prod.website-files.com/68d3ac079a10da70917c11f6/68f4b97e470178262d819ef5_opengraph_dpdi.png","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-du-pain-et-des-idees"},{"id":"canal-food-holybelly","name":"Holybelly 5","coordinates":[48.8723,2.3606],"description":"Holybelly 5 is the brunch-and-coffee anchor near the canal, useful when the morning needs a proper seated meal before walking. Expect demand and build timing around it.","price":"$$","priceSource":"Google Maps / Paris dining guides","photo":"https://holybellycafe.com/OpenGraph.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-holybelly-5"},{"id":"canal-food-early-june","name":"Early June","coordinates":[48.8739,2.3621],"description":"Early June gives the canal a wine-led, rotating-kitchen meal that feels current and neighborhood-specific. Save it for travelers who like seasonal plates and a less formal dinner rhythm.","price":"$$","priceSource":"Eater / Google Maps","photo":"https://early-june.fr/wp-content/uploads/2020/09/Background.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-early-june"},{"id":"canal-food-chez-prune","name":"Chez Prune","coordinates":[48.8726,2.3634],"description":"Chez Prune is the canal-side cafe standby for lunch, aperitif, or a simple meal with the water close by. Its value is meeting-point energy and location rather than culinary surprise.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://upload.wikimedia.org/wikipedia/commons/8/8d/Chez_Prune_1%2C_Paris_29_May_2014.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-chez-prune"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-bars', 'paris-canal-saint-martin-bars', 'Nightlife', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-bars","slug":"paris-canal-saint-martin-bars","seoSlug":"best-bars","seoTitle":"Best Bars in Canal Saint-Martin, Paris","seoDescription":"Best bars in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Canal Drinks With a Route","description":"Canal Saint-Martin nights are strongest when they stay walkable: one proper cocktail, a music terrace, an atmospheric indoor bar, and a casual meeting-point cafe. The guide keeps the canal from becoming only bank-side wandering.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-nightlife-gravity","name":"Gravity Bar","coordinates":[48.8728,2.3622],"description":"Gravity Bar is the cocktail stop for a canal night that wants design and sharper drinks before the route loosens up. It is best for a focused first drink near Rue des Vinaigriers.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://media.cntraveler.com/photos/5a80a85d52e7b4436ff64db7/16:9/w_1000,c_limit/Gravity_JB-Lemal_2018_4---copie.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-gravity-bar"},{"id":"canal-nightlife-la-meduse","name":"La Meduse","coordinates":[48.8791,2.3671],"description":"La Meduse gives the canal a cocktail-and-natural-wine option right by the water, with enough food to keep the evening flexible. Use it when the night should stay canal-side but still feel deliberate.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://media.timeout.com/images/105202137/750/562/image.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-la-meduse"},{"id":"canal-nightlife-point-ephemere","name":"Point Ephemere","coordinates":[48.8819,2.3686],"description":"Point Ephemere gives the canal a music, terrace, and art-space anchor farther north. It works when the night needs programming or a looser crowd instead of another polished cocktail room.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://images.prismic.io/pointf/adfVVJ1ZCF7ETC06_PInata.jpg?auto=format&q=25&fm=webp&width=640","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-point-ephemere"},{"id":"canal-nightlife-comptoir-general","name":"Le Comptoir General","coordinates":[48.8727,2.3638],"description":"Le Comptoir General is the eclectic canal room for groups that want decor, drinks, and a moodier indoor option after the banks get crowded. It is best saved for atmosphere-forward evenings.","price":"$$","priceSource":"Time Out / Google Maps","photo":"https://lecomptoirgeneral.com/wp-content/uploads/2021/02/COMPTOIR-01-2.png","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-comptoir-general"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-parks-and-walks', 'paris-canal-saint-martin-parks-and-walks', 'Nature', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-parks-and-walks","slug":"paris-canal-saint-martin-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in Canal Saint-Martin, Paris","seoDescription":"Best parks and walks in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Locks, Banks, and East-Side Air","description":"Canal Saint-Martin''s outdoor value is linear: locks, bridges, pocket gardens, and a walk north toward wider water. This guide gives the neighborhood air without pretending it is a park district.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-nature-locks","name":"Canal Saint-Martin Locks","coordinates":[48.8721,2.3648],"description":"The Canal Saint-Martin locks are the neighborhood''s outdoor spine, turning a simple walk into a sequence of bridges, water, and street corners. Use them between bakery, lunch, and evening drinks.","photo":"https://images.unsplash.com/photo-1511739001486-6bfe10ce785f?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-canal-saint-martin-locks"},{"id":"canal-nature-villemin","name":"Jardin Villemin","coordinates":[48.8764,2.3614],"description":"Jardin Villemin gives the canal a practical green pause near Gare de l''Est and the central banks. It is useful for shade, families, or a break from narrow sidewalks.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-villemin"},{"id":"canal-nature-frederic-lemaitre","name":"Square Frederic-Lemaitre","coordinates":[48.871,2.367],"description":"Square Frederic-Lemaitre is a small green stop by the canal and Republique edge, helpful when the route needs a quieter bench between bars and water. It is a pause, not a destination.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-square-frederic-lemaitre"},{"id":"canal-nature-bassin-villette","name":"Bassin de la Villette","coordinates":[48.884,2.371],"description":"Bassin de la Villette extends the canal walk into wider water, picnic edges, and summer activity. Use it when the route can continue north instead of looping back immediately.","photo":"https://images.unsplash.com/photo-1511739001486-6bfe10ce785f?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-bassin-de-la-villette"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-culture', 'paris-canal-saint-martin-culture', 'Culture', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-culture","slug":"paris-canal-saint-martin-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Canal Saint-Martin, Paris","seoDescription":"Best culture in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Art Spaces, Courtyards, and Republique Edges","description":"Canal Saint-Martin culture is informal: music rooms, event spaces, old hospital courtyards, and civic squares. This guide keeps the neighborhood''s creative stops tied to the water and evening route.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-culture-point-ephemere","name":"Point Ephemere","coordinates":[48.8819,2.3686],"description":"Point Ephemere is the canal''s art-and-music anchor, with exhibitions, concerts, and terrace energy beside the water. Check the program before making it the center of the route.","photo":"https://images.prismic.io/pointf/adfVVJ1ZCF7ETC06_PInata.jpg?auto=format&q=25&fm=webp&width=640","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-point-ephemere"},{"id":"canal-culture-comptoir-general","name":"Le Comptoir General","coordinates":[48.8727,2.3638],"description":"Le Comptoir General works as a cultural room as much as a bar, with decor, events, and an atmospheric courtyard feel. Use it for a night that wants setting and social energy.","photo":"https://lecomptoirgeneral.com/wp-content/uploads/2021/02/COMPTOIR-01-2.png","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-le-comptoir-general"},{"id":"canal-culture-hopital-saint-louis","name":"Hopital Saint-Louis Courtyard","coordinates":[48.8738,2.3687],"description":"The Hopital Saint-Louis courtyard is a historic architectural pause close to the canal, useful for travelers who want a quieter layer of the neighborhood. Respect access rules and keep the stop brief.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-hopital-saint-louis-courtyard"},{"id":"canal-culture-republique","name":"Place de la Republique","coordinates":[48.8675,2.363],"description":"Place de la Republique gives the canal route civic scale and a clear southern meeting point. It works as orientation before moving north toward the locks and bars.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-place-de-la-republique"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-hotels-and-hostels', 'paris-canal-saint-martin-hotels-and-hostels', 'Stay', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-hotels-and-hostels","slug":"paris-canal-saint-martin-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in Canal Saint-Martin, Paris","seoDescription":"Best hotels and hostels in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Canal Hotels and Social Bases","description":"Staying around Canal Saint-Martin is about east-side food, bars, train access, and social energy. This guide mixes canal-facing hotels, design hostels, and practical bases that serve the waterline route.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-stay-citizen","name":"Le Citizen Hotel","coordinates":[48.8726,2.3643],"description":"Le Citizen Hotel is the canal-facing boutique stay for travelers who want the water, cafes, and bars directly outside. It is best when the canal is the daily base, not just one evening plan.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://cdn.prod.website-files.com/688e265d139102e1191b2a7e/68de7e48c27d5de0af98986d_ILO%20OPEN%20GRAPH.png","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-le-citizen-hotel"},{"id":"canal-stay-generator","name":"Generator Paris","coordinates":[48.8795,2.3696],"description":"Generator Paris is the design-hostel option near Canal Saint-Martin, with dorms, private rooms, and social common spaces. It fits budget travelers who value canal access over old-city charm.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://staygenerator.com/web/media/widget-spaces-rooms/paris/rooms-photos-2025/generator-paris-hostel-deluxe-king-room-1.jpg?mode=max&quality=100&v=202508261351","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-generator-paris"},{"id":"canal-stay-providence","name":"Hotel Providence","coordinates":[48.8701,2.3568],"description":"Hotel Providence gives the canal-Republique edge a design-led hotel with strong food and bar access nearby. Use it when the stay should bridge the canal, the 10th, and central Right Bank routes.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://hotelprovidenceparis.com/wp-content/uploads/2015/09/1w2a2225-5.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-providence"},{"id":"canal-stay-st-christophers","name":"St Christopher''s Inn Canal","coordinates":[48.8868,2.3756],"description":"St Christopher''s Inn Canal is the larger social-hostel base north on the waterline, useful for budget travelers who want dorms, events, and Villette access. It is more canal extension than old-center stay.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://images.ctfassets.net/wqkd101r9z5s/7JuethZ3p5V7zQHyubsMIM/d25dad4126547d595f20cea943636537/iStock-1133449890_copy.jpg?w=720&q=85","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-st-christopher-s-inn-canal"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-canal-saint-martin-things-to-do', 'paris-canal-saint-martin-things-to-do', 'Activities', 'France', 'Paris', 'Canal Saint-Martin', '{"id":"list-paris-canal-saint-martin-things-to-do","slug":"paris-canal-saint-martin-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Canal Saint-Martin, Paris","seoDescription":"Best things to do in Canal Saint-Martin, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"A Waterline Day Into Night","description":"Canal Saint-Martin activities work as a sequence: bakery, locks, shopping streets, Republique, wider water, and music or drinks. This guide keeps the day linear so the neighborhood feels easy to follow.","url":"https://www.google.com/maps/search/Canal%20Saint-Martin%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"Canal Saint-Martin","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"canal-activity-bakery-locks","name":"Bakery and Locks Morning","coordinates":[48.8721,2.3648],"description":"A bakery and locks morning starts at Du Pain et des Idees, then follows bridges and water north. It is the easiest way to make the canal feel like a route, not a single photo stop.","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-bakery-and-locks-morning"},{"id":"canal-activity-vinaigriers","name":"Rue des Vinaigriers and Canal Shops","coordinates":[48.873,2.362],"description":"Rue des Vinaigriers and the canal shops give the neighborhood a browsing spine with cafes, small retailers, and bars nearby. Use it between brunch and aperitif.","photo":"https://images.unsplash.com/photo-1511739001486-6bfe10ce785f?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-rue-des-vinaigriers-and-canal-shops"},{"id":"canal-activity-republique-canal","name":"Republique to the Canal","coordinates":[48.8675,2.363],"description":"Republique to the canal is the practical southern approach, linking a major square to quieter bridges and water. It works when friends need an easy meeting point before wandering.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-republique-to-the-canal"},{"id":"canal-activity-point-ephemere-night","name":"Point Ephemere Night","coordinates":[48.8819,2.3686],"description":"A Point Ephemere night turns the canal into music, terrace, and late programming. Check the event calendar and build dinner or drinks around the show rather than hoping something is on.","photo":"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-point-ephemere-night"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-7th-arrondissement-restaurants', 'paris-7th-arrondissement-restaurants', 'Food', 'France', 'Paris', '7th Arrondissement', '{"id":"list-paris-7th-arrondissement-restaurants","slug":"paris-7th-arrondissement-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in 7th Arrondissement, Paris","seoDescription":"Best restaurants in 7th Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Monument-Side Meals With Purpose","description":"The 7th needs food stops that can stand up to Eiffel, Invalides, Rodin, and Orsay days. This guide balances destination dining, classic bistros, and practical cafes so the district is more than monument logistics.","url":"https://www.google.com/maps/search/7th%20Arrondissement%20Restaurants%20Paris","category":"Food","location":{"city":"Paris","neighborhood":"7th Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"seventh-food-david-toutain","name":"David Toutain","coordinates":[48.8617,2.3048],"description":"In the 7th, David Toutain is the destination-dining counterweight to monument routes, with plant-led menus and a serious reservation posture near Invalides and the Eiffel Tower. Plan it as the day''s main meal.","price":"$$$","priceSource":"MICHELIN Guide / David Toutain official","photo":"https://images.getbento.com/accounts/ff03f9e731b42b40fa602140d58b60a7/media/images/8088DT-09-2025_1302.jpg?w=1200&fit=crop&auto=compress,format&cs=origin&crop=focalpoint&fp-x=0.5&fp-y=0.5","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-david-toutain"},{"id":"seventh-food-arpege","name":"Arpege","coordinates":[48.8555,2.3162],"description":"Arpege is the vegetable-driven fine-dining landmark that makes the 7th a serious food destination. Use it only when the trip has room for a high-budget, high-commitment reservation.","price":"$$$","priceSource":"MICHELIN Guide / Google Maps","photo":"https://www.alain-passard.com/wp-content/uploads/2022/02/Arpegesalle4-1000x800.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-arpege"},{"id":"seventh-food-fontaine-mars","name":"La Fontaine de Mars","coordinates":[48.8587,2.3044],"description":"La Fontaine de Mars is the classic bistro choice near Rue Saint-Dominique and the Eiffel side. It works when the group wants a traditional meal with a strong neighborhood address.","price":"$$$","priceSource":"Google Maps / Paris dining guides","photo":"https://www.fontaine-de-mars.com/wp-content/uploads/2025/12/DConstantini_Exterieur_6-69.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-la-fontaine-de-mars"},{"id":"seventh-food-cafe-varenne","name":"Cafe Varenne","coordinates":[48.855,2.3194],"description":"Cafe Varenne is the practical brasserie near Rodin, Invalides, and government-quarter walks. Use it when the museum day needs a reliable lunch or dinner without a destination-dining commitment.","price":"$$","priceSource":"Google Maps / local dining guides","photo":"https://www.urbansider.com/wp-content/uploads/Categories/Bars-amp-Cafes/cafe-varenne-interior-1-2.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-cafe-varenne"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-7th-arrondissement-bars', 'paris-7th-arrondissement-bars', 'Nightlife', 'France', 'Paris', '7th Arrondissement', '{"id":"list-paris-7th-arrondissement-bars","slug":"paris-7th-arrondissement-bars","seoSlug":"best-bars","seoTitle":"Best Bars in 7th Arrondissement, Paris","seoDescription":"Best bars in 7th Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"River Drinks and Polished Nightcaps","description":"The 7th is not a late-night district, so the best after-dark stops are intentional: river barges, hotel-adjacent bars, rooftops, and polished cafes. This guide keeps evenings close to Eiffel-side routes.","url":"https://www.google.com/maps/search/7th%20Arrondissement%20Bars%20Paris","category":"Nightlife","location":{"city":"Paris","neighborhood":"7th Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"seventh-nightlife-fitzgerald","name":"Fitzgerald","coordinates":[48.8572,2.3078],"description":"Fitzgerald gives the 7th a discreet cocktail-bar format behind a restaurant setting near Rue Saint-Dominique. Use it when the night wants a hidden-room feel without leaving the Eiffel side.","price":"$$$","priceSource":"Time Out / Google Maps","photo":"https://cdn.prod.website-files.com/657ebf942cf08a351e21c1b1/658337e9bf17d5c7272c21ed_FITZ_HERO_DT.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-fitzgerald"},{"id":"seventh-nightlife-rosa-bonheur","name":"Rosa Bonheur sur Seine","coordinates":[48.862,2.3069],"description":"Rosa Bonheur sur Seine brings the 7th to the river with a barge-party format that works better for groups and warm evenings than quiet cocktails. Check the night and crowd before relying on it.","price":"$$","priceSource":"Google Maps / local nightlife guides","photo":"https://rosabonheur.fr/wp-content/uploads/2024/06/Seine-RosaB-0822-LevietPhoto-8955-uai-2133x1600.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-rosa-bonheur-sur-seine"},{"id":"seventh-nightlife-les-ombres","name":"Les Ombres","coordinates":[48.861,2.2978],"description":"Les Ombres is the Eiffel-view rooftop drink and dinner setting above Quai Branly, useful when the night is about scenery and occasion. Book ahead if the view is the point.","price":"$$$","priceSource":"Google Maps / official venue site","photo":"https://www.lesombres-restaurant.com/wp-content/uploads/2022/11/Les_Ombres_20-10-20-Julien-Mouffron-Gardner_7990-600x600.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-les-ombres"},{"id":"seventh-nightlife-recrutement","name":"Le Recrutement Cafe","coordinates":[48.8568,2.304],"description":"Le Recrutement Cafe is the casual Rue Saint-Dominique terrace for a simple drink after Eiffel or Invalides walking. Its value is location, people-watching, and low planning pressure.","price":"$$","priceSource":"Google Maps / local nightlife guides","photo":"https://upload.wikimedia.org/wikipedia/commons/3/34/Le_Recrutement_Cafe_in_Paris.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-recrutement-cafe"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-7th-arrondissement-parks-and-walks', 'paris-7th-arrondissement-parks-and-walks', 'Nature', 'France', 'Paris', '7th Arrondissement', '{"id":"list-paris-7th-arrondissement-parks-and-walks","slug":"paris-7th-arrondissement-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in 7th Arrondissement, Paris","seoDescription":"Best parks and walks in 7th Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Lawns, Gardens, and River Space","description":"Outdoor time in the 7th should soften monument days: Champ de Mars, Rodin''s sculpture garden, Invalides lawns, and Seine edges. This guide gives the district air around its biggest tickets.","url":"https://www.google.com/maps/search/7th%20Arrondissement%20Parks%20and%20Walks%20Paris","category":"Nature","location":{"city":"Paris","neighborhood":"7th Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"seventh-nature-champ-mars","name":"Champ de Mars","coordinates":[48.8556,2.2986],"description":"Champ de Mars is the Eiffel-side lawn and view corridor, useful when the tower needs space around it. Use it early, late, or as a picnic pause rather than a midday crowd trap.","photo":"https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-champ-de-mars"},{"id":"seventh-nature-invalides","name":"Esplanade des Invalides","coordinates":[48.8606,2.313],"description":"Esplanade des Invalides gives the 7th a broad green axis between the river and the dome. It works as a walking reset between Orsay, Rodin, and Invalides.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-esplanade-des-invalides"},{"id":"seventh-nature-rodin-garden","name":"Musee Rodin Sculpture Garden","coordinates":[48.8554,2.3158],"description":"The Musee Rodin sculpture garden is the district''s best art-and-air combination, with outdoor works and calmer pacing than larger museums. Use it when culture needs breathing room.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-rodin-sculpture-garden"},{"id":"seventh-nature-solferino","name":"Port de Solferino Seine Walk","coordinates":[48.861,2.315],"description":"Port de Solferino gives the 7th a river route between Orsay, Invalides, and Eiffel-side bridges. It is the easiest way to keep the day scenic without adding another ticket.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-port-de-solferino-seine-walk"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-7th-arrondissement-culture', 'paris-7th-arrondissement-culture', 'Culture', 'France', 'Paris', '7th Arrondissement', '{"id":"list-paris-7th-arrondissement-culture","slug":"paris-7th-arrondissement-culture","seoSlug":"best-culture","seoTitle":"Best Culture in 7th Arrondissement, Paris","seoDescription":"Best culture in 7th Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Eiffel-Side Culture With Context","description":"The 7th needs a guide because its icons can become isolated errands. This route connects the Eiffel Tower with Orsay, Rodin, Quai Branly, Invalides, gardens, and river walks so the district works as a full cultural day.","url":"https://www.google.com/maps/search/7th%20Arrondissement%20Culture%20Paris","category":"Culture","location":{"city":"Paris","neighborhood":"7th Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"seventh-culture-eiffel","name":"Eiffel Tower","coordinates":[48.8584,2.2945],"description":"The Eiffel Tower is the unavoidable 7th-arrondissement anchor, but it works best when the ticket, view, and surrounding walk are planned together. Pair it with the river or Champ de Mars.","photo":"https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-eiffel-tower"},{"id":"seventh-culture-orsay","name":"Musee d''Orsay","coordinates":[48.8599,2.3266],"description":"Musee d''Orsay gives the 7th a museum anchor with enough scale for a half day but less sprawl than the Louvre. It pairs naturally with the Seine, Rodin, and Saint-Germain.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-d-orsay"},{"id":"seventh-culture-rodin","name":"Musee Rodin","coordinates":[48.8554,2.3158],"description":"Musee Rodin is the district''s garden-and-sculpture pause, a calmer stop that can soften a monument-heavy day. Use it between Orsay, Invalides, and Eiffel-side walks.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-rodin"},{"id":"seventh-culture-invalides","name":"Les Invalides","coordinates":[48.8566,2.3126],"description":"Les Invalides anchors the 7th with military history, grand architecture, and Napoleon''s tomb. It works well as the middle of a westward day between Rodin, the river, and the Eiffel Tower.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-les-invalides"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-7th-arrondissement-hotels-and-hostels', 'paris-7th-arrondissement-hotels-and-hostels', 'Stay', 'France', 'Paris', '7th Arrondissement', '{"id":"list-paris-7th-arrondissement-hotels-and-hostels","slug":"paris-7th-arrondissement-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in 7th Arrondissement, Paris","seoDescription":"Best hotels and hostels in 7th Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"Eiffel-Side Hotels for Quiet Returns","description":"Staying in the 7th is about calm, monuments, museums, and polished streets rather than late nightlife. This guide focuses on hotels that keep Eiffel, Rodin, Invalides, and Orsay days walkable.","url":"https://www.google.com/maps/search/7th%20Arrondissement%20Hotels%20and%20Hostels%20Paris","category":"Stay","location":{"city":"Paris","neighborhood":"7th Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"seventh-stay-la-comtesse","name":"Hotel La Comtesse","coordinates":[48.8539,2.3065],"description":"Hotel La Comtesse is the Eiffel-view boutique stay for travelers who want Champ de Mars, Rue Cler, and Invalides close by. It works when view and location outweigh big-hotel amenities.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://comtesse-hotel.com/_novaimg/4317200-1346800_0_303_4800_2615_2200_1200.rc.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-la-comtesse"},{"id":"seventh-stay-le-walt","name":"Hotel Le Walt","coordinates":[48.8548,2.3089],"description":"Hotel Le Walt gives the 7th a smaller hotel base near Ecole Militaire and the Eiffel route. Use it when the plan needs quiet returns after museum and monument days.","price":"$$","priceSource":"Google Travel / Tripadvisor","photo":"https://d13rhhrxazfw7c.cloudfront.net/cache/img/dbe9def1157870691d427b027851ce61c5154ca9-dbe9de-1200-627-crop.jpg?q=1718102689","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-le-walt"},{"id":"seventh-stay-jk-place","name":"J.K. Place Paris","coordinates":[48.8604,2.3183],"description":"J.K. Place Paris is the design-luxury stay near the Seine, Orsay, and Invalides, with a more intimate mood than palace hotels. It fits travelers who want polish without Right Bank scale.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://www.jkplaces.com/jkparis/wp-content/themes/startup_pro/inc/php-global/s-image/index.php?img=/var/www/vhosts/jkplaces.com/httpdocs/jkparis/wp-content/uploads//2025/04/jkparis_5stars-hotel.jpg&mod=3&w=1456","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-j-k-place-paris"},{"id":"seventh-stay-montalembert","name":"Hotel Montalembert","coordinates":[48.8565,2.327],"description":"Hotel Montalembert sits on the Saint-Germain edge of the 7th, useful for Orsay, galleries, and Left Bank meals. Choose it when the stay should bridge the 7th and Saint-Germain.","price":"$$$","priceSource":"Google Travel / Tripadvisor","photo":"https://d1uj7wsed4nlat.cloudfront.net/cache/img/ff862722b3c71ea1db76ea2c288926f09b962f8e-ff8627-1200-627-crop.jpg?q=1724323756","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-montalembert"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-7th-arrondissement-things-to-do', 'paris-7th-arrondissement-things-to-do', 'Activities', 'France', 'Paris', '7th Arrondissement', '{"id":"list-paris-7th-arrondissement-things-to-do","slug":"paris-7th-arrondissement-things-to-do","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in 7th Arrondissement, Paris","seoDescription":"Best things to do in 7th Arrondissement, Paris, selected for source support, neighborhood fit, and useful saved-map routing.","title":"A Westward Museum and Monument Day","description":"The 7th works best as a westward route with art, gardens, river views, and one Eiffel-side moment. This guide makes the district feel like a full day rather than separate errands for photos and tickets.","url":"https://www.google.com/maps/search/7th%20Arrondissement%20Things%20to%20Do%20Paris","category":"Activities","location":{"city":"Paris","neighborhood":"7th Arrondissement","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"seventh-activity-orsay-rodin-invalides","name":"Orsay, Rodin, and Invalides","coordinates":[48.8576,2.318],"description":"Orsay, Rodin, and Invalides create the strongest cultural route in the 7th, moving from art to sculpture garden to military history. Use it as a slow museum day with outdoor pauses.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-orsay-rodin-and-invalides"},{"id":"seventh-activity-eiffel-champ","name":"Eiffel Tower and Champ de Mars","coordinates":[48.8584,2.2945],"description":"Eiffel Tower and Champ de Mars is the classic district activity, but it works best with timing and a plan for the surrounding lawns and streets. Avoid making the tower the only stop.","photo":"https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-eiffel-tower-and-champ-de-mars"},{"id":"seventh-activity-quai-branly-river","name":"Quai Branly and River Walk","coordinates":[48.8609,2.2976],"description":"Quai Branly and the river walk add cultural substance and waterline movement beside the Eiffel Tower. Use it when the area needs more than a view.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-quai-branly-and-river-walk"},{"id":"seventh-activity-rue-cler","name":"Rue Cler and Rue Saint-Dominique","coordinates":[48.856,2.306],"description":"Rue Cler and Rue Saint-Dominique give the 7th a food-shopping and cafe activity between monuments. It is useful for a lighter block before dinner or after Champ de Mars.","photo":"https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-rue-cler-and-rue-saint-dominique"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-citywide-restaurants', 'paris-best-restaurants', 'Food', 'France', 'Paris', null, '{"id":"list-paris-citywide-restaurants","slug":"paris-best-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Paris","seoDescription":"Best restaurants in Paris for classic bistros, wine-led rooms, bakeries, seafood, falafel counters, and modern reservation dinners by arrondissement.","title":"Bistros, Bakeries, and Modern Reservations","description":"Paris food needs more than a trophy reservation: classic bistros, natural-wine rooms, bakeries, falafel counters, seafood waits, and modern tasting menus all solve different parts of the route. Use this to anchor meals by arrondissement instead of chasing one generic best-of list.","url":"https://www.google.com/maps/search/best+restaurants+paris","category":"Food","location":{"city":"Paris","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"paris-food-bistrot-tournelles","name":"Bistrot des Tournelles","coordinates":[48.8555,2.366],"description":"Bistrot des Tournelles is the Marais classic-bistro anchor: old-room energy, steak frites and terrines, and enough current editorial support to avoid feeling like a nostalgia trap. It is best when the route needs a proper French dinner near Place des Vosges instead of another snack crawl.","price":"$$","priceSource":"The Infatuation / Google Maps","photo":"https://www.bistrotdestournelles.com/i/bistrot-des-tournelles-554913/3/5/8/3/0/5/1/5/1/3/6/9/2/1659108926_161/322ce864025eb6fe3b82efab6e96034b.website.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-bistrot-des-tournelles"},{"id":"paris-food-brasserie-lipp","name":"Brasserie Lipp","coordinates":[48.8535,2.3332],"description":"Brasserie Lipp gives Saint-Germain a literary brasserie stop with real use in a food guide: polished room, Alsatian-leaning classics, and a see-and-be-seen lunch or dinner that belongs to the boulevard. Book it when history and room tone matter as much as the plate.","price":"$$$","priceSource":"The Infatuation / Google Maps","photo":"https://ugc.zenchef.com/3/4/5/9/5/3/1/5/1/3/7/1/9/1714144479_381/27da576e9c340bdf3ca689ae48b78286.website.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-brasserie-lipp"},{"id":"paris-food-le-baratin","name":"Le Baratin","coordinates":[48.8731,2.3857],"description":"Le Baratin is the Belleville bistro that still pulls chefs across town for Raquel Carena''s blackboard cooking and natural-wine soul. It earns its place because it shows Paris food moving east: personal, seasonal, a little unruly, and better as a planned dinner than a casual drop-in.","price":"$$","priceSource":"Eater / Time Out / MICHELIN Guide","photo":"https://img.restaurantguru.com/w550/h367/rc91-Le-Baratin-interior-2024-12-2.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-le-baratin"},{"id":"paris-food-septime","name":"Septime","coordinates":[48.8535,2.3829],"description":"Septime is the modern-reservation benchmark in the 11th: precise, seasonal, and still a reference point for Paris bistronomy. Its value is not convenience; it is a protected meal that explains why the Charonne corridor matters to contemporary Paris dining.","price":"$$$","priceSource":"MICHELIN Guide / Eater","photo":"https://assets.bonappetit.com/photos/58e295d165366d7ba908130a/16:9/w_1000,c_limit/Septime%20-%20Table.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-septime"},{"id":"paris-food-clamato","name":"Clamato","coordinates":[48.8536,2.3828],"description":"Clamato is the more flexible seafood sibling to Septime, useful when the trip needs oysters, small plates, and high-quality produce without a formal tasting-menu commitment. The no-reservation rhythm means it works best with timing discipline and a backup nearby.","price":"$$","priceSource":"MICHELIN Guide / Paris by Mouth","photo":"https://res.cloudinary.com/the-infatuation/image/upload/f_auto/q_auto/v1724964967/Clamato_interior_ksenxx.jpg","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-clamato"},{"id":"paris-food-du-pain-idees","name":"Du Pain et des Idees","coordinates":[48.8719,2.3622],"description":"Du Pain et des Idees is the bakery stop that makes Canal Saint-Martin mornings feel intentional. Use it for escargot pastries, bread, and a compact breakfast route before the canal, Republique, or north Marais; it is a meal-format pick, not just a photo of a facade.","price":"$","priceSource":"Eater / Google Maps","photo":"https://cdn.prod.website-files.com/68d3ac079a10da70917c11f6/68f4b97e470178262d819ef5_opengraph_dpdi.png","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-du-pain-et-des-idees"},{"id":"paris-food-david-toutain","name":"David Toutain","coordinates":[48.8617,2.3048],"description":"David Toutain gives the citywide food guide a Left Bank tasting-menu anchor, with plant-led cooking and a serious reservation posture near Invalides and the Eiffel Tower. It belongs here for travelers planning one high-budget meal around the museum day.","price":"$$$","priceSource":"MICHELIN Guide / David Toutain official","photo":"https://images.getbento.com/accounts/ff03f9e731b42b40fa602140d58b60a7/media/images/8088DT-09-2025_1302.jpg?w=1200&fit=crop&auto=compress,format&cs=origin&crop=focalpoint&fp-x=0.5&fp-y=0.5","hours":{"default":"Hours and booking rules vary; confirm current service before going."},"poiId":"poi-france-paris-david-toutain"}],"sources":[{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-citywide-nightlife', 'paris-best-bars-nightlife', 'Nightlife', 'France', 'Paris', null, '{"id":"list-paris-citywide-nightlife","slug":"paris-best-bars-nightlife","seoSlug":"best-bars","seoTitle":"Best Bars and Nightlife in Paris","seoDescription":"Best bars and nightlife in Paris for cocktail rooms, wine bars, jazz, Canal Saint-Martin evenings, Marais drinks, and late Pigalle energy.","title":"Wine Bars, Cocktails, Jazz, and Pigalle","description":"Paris nights work best when the format is clear: natural wine before dinner, trophy cocktails in the Marais or Bourse, jazz with tickets, canal terraces, or later Pigalle rooms. This guide keeps after-dark planning tied to geography instead of sending every night across town.","url":"https://www.google.com/maps/search/best+bars+nightlife+paris","category":"Nightlife","location":{"city":"Paris","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"paris-nightlife-bar-nouveau","name":"Bar Nouveau","coordinates":[48.8623,2.3579],"description":"Bar Nouveau is the Marais cocktail trophy with a real reason to queue: World 50 Best recognition, Art Nouveau design, and a small-room format that rewards early timing. Use it for one focused drink before the night spreads into dinner, galleries, or another bar.","price":"$$$","priceSource":"World''s 50 Best Bars","photo":"https://barnouveau.fr/wp-content/uploads/2026/04/IMG_2109-2.png","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-bar-nouveau"},{"id":"paris-nightlife-cambridge","name":"The Cambridge Public House","coordinates":[48.8618,2.3632],"description":"The Cambridge Public House makes the guide because it bridges pub ease and Paris cocktail precision. It is useful for groups that want serious drinks without whispery formality, plus a Marais location that can start or end a wider Right Bank night.","price":"$$","priceSource":"World''s 50 Best Bars","photo":"https://ugc.zenchef.com/3/6/0/6/8/5/1/5/6/7/6/9/4/1760366013_207/a4b7ed07993593cf70eac7ad287d9bbf.website.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-the-cambridge-public-house"},{"id":"paris-nightlife-danico","name":"Danico","coordinates":[48.8666,2.3399],"description":"Danico is the polished Galerie Vivienne cocktail room, backed by World 50 Best and useful when the night needs a destination bar near Palais Royal, Bourse, or the covered passages. It is more special-occasion cocktail stop than loose neighborhood bar.","price":"$$$","priceSource":"World''s 50 Best Bars","photo":"https://www.daroco.com/wp-content/uploads/2024/02/AM2A5871-2100x1400.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-danico"},{"id":"paris-nightlife-septime-cave","name":"Septime La Cave","coordinates":[48.8539,2.3823],"description":"Septime La Cave gives the 11th a wine-led first or final stop near the Charonne restaurant cluster. Save it when natural wine, small plates, and a standing-room mood suit the night better than a full second dinner or a polished cocktail lounge.","price":"$$","priceSource":"Eater / Google Maps","photo":"https://parisbymouth.com/wp-content/uploads/2014/09/septime-cave-for-pbm.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-septime-la-cave"},{"id":"paris-nightlife-duc-lombards","name":"Le Duc des Lombards","coordinates":[48.8593,2.3476],"description":"Le Duc des Lombards is the central jazz anchor, useful when nightlife should be tickets and musicianship rather than only bars. Its Chatelet position makes it easy to add after dinner, but the best version of the night starts with the show calendar.","price":"$$","priceSource":"Paris venue listings / Google Maps","photo":"https://ducdeslombards.com/sites/default/files/ducdeslombards/styles/16x9_1280/public/ged/import/1807-1771947235.jpg?itok=y86lFejr","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-le-duc-des-lombards"},{"id":"paris-nightlife-la-gare-le-gore","name":"La Gare / Le Gore","coordinates":[48.8927,2.3839],"description":"La Gare / Le Gore pushes the guide toward La Villette: jazz upstairs, late electronic nights below, and a looser edge than central cocktail rooms. Use it when the evening can commit to the northeast instead of trying to fold it into a museum day.","price":"$","priceSource":"Visit Paris Region","photo":"https://res.cloudinary.com/du5jifpgg/image/upload/t_opengraph_image/Surcharge-APIDAE/La_Gare_le_Gore.jpg","hours":{"default":"Evening hours and event schedules vary; confirm before going."},"poiId":"poi-france-paris-la-gare-le-gore"}],"sources":[{"name":"The World''s 50 Best Bars - Bar Nouveau","url":"https://www.theworlds50best.com/bars/the-list/bar-nouveau.html"},{"name":"The World''s 50 Best Bars - The Cambridge Public House","url":"https://www.theworlds50best.com/bars/the-list/the-cambridge-public-house.html"},{"name":"The World''s 50 Best Bars - Danico","url":"https://www.theworlds50best.com/bars/the-list/danico.html"},{"name":"Time Out - Best cocktail bars in Paris","url":"https://www.timeout.com/paris/en/bars-pubs/best-cocktail-bars-in-paris"},{"name":"Time Out - Canal Saint-Martin bars","url":"https://www.timeout.com/paris/en/bars-pubs/bars-in-canal-saint-martin-ourcq-villette"},{"name":"Visit Paris Region - La Gare / Le Gore","url":"https://www.visitparisregion.com/en/la-gare-le-gore"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-citywide-culture', 'paris-best-culture-citywide', 'Culture', 'France', 'Paris', null, '{"id":"list-paris-citywide-culture","slug":"paris-best-culture-citywide","seoSlug":"best-culture","seoTitle":"Best Culture in Paris","seoDescription":"Best culture in Paris for major museums, Gothic interiors, Marais houses, opera architecture, sculpture gardens, and ticketed historic sites.","title":"Museum Weight and Smaller Rooms","description":"Paris culture is strongest when the heavyweight museums have room around them: Louvre or Orsay as anchors, then chapels, house museums, opera architecture, sculpture gardens, and darker underground history. Use this to build days with one big ticket and one smaller counterweight.","url":"https://www.google.com/maps/search/best+culture+paris","category":"Culture","location":{"city":"Paris","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"paris-culture-louvre","name":"Musee du Louvre","coordinates":[48.8606,2.3376],"description":"The Louvre is the cultural heavyweight, but it works only when treated as a route rather than a dare. Book a time slot, choose a wing or theme, and pair the museum with Tuileries, Palais Royal, or a nearby meal so the day has shape beyond crowd management.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-du-louvre"},{"id":"paris-culture-orsay","name":"Musee d''Orsay","coordinates":[48.8599,2.3266],"description":"Musee d''Orsay gives Paris a more manageable blockbuster than the Louvre, with Impressionism, sculpture, and the converted railway-station setting all in one Left Bank stop. It pairs naturally with Saint-Germain, the Seine, Rodin, or a 7th-arrondissement day.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-d-orsay"},{"id":"paris-culture-sainte-chapelle","name":"Sainte-Chapelle","coordinates":[48.8554,2.345],"description":"Sainte-Chapelle is the short, high-impact Gothic stop for stained glass and Ile de la Cite context. It is best saved with timed entry and a nearby walk to Notre-Dame, the Conciergerie, or the river instead of being squeezed between unrelated cross-town stops.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-sainte-chapelle"},{"id":"paris-culture-picasso","name":"Musee Picasso Paris","coordinates":[48.8599,2.3623],"description":"Musee Picasso Paris gives the citywide culture list a Marais museum that is focused enough to pair with food and gallery detours. The Hotel Sale setting, collection depth, and easy Place des Vosges approach keep the stop substantial without becoming an all-day block.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-picasso-paris"},{"id":"paris-culture-palais-garnier","name":"Palais Garnier","coordinates":[48.8719,2.3316],"description":"Palais Garnier adds architecture and performance history to a Right Bank plan. Self-guided visits are strongest when the auditorium access is treated as a bonus, not a guarantee, and the stop is paired with passages, department stores, or a cocktail nearby.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-palais-garnier"},{"id":"paris-culture-rodin","name":"Musee Rodin","coordinates":[48.8554,2.3158],"description":"Musee Rodin is the 7th-arrondissement cultural pressure valve: sculpture, mansion rooms, and garden time in a calmer frame than the biggest museums. It works especially well between Invalides, Orsay, and an Eiffel-side walk.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-musee-rodin"},{"id":"paris-culture-catacombs","name":"Paris Catacombs","coordinates":[48.8338,2.3324],"description":"The Catacombs give Paris a darker, ticketed counterweight to palace and museum days. Because access is capacity-controlled and the visit is physically specific, build it as a deliberate south-side block rather than a spontaneous add-on.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-paris-catacombs"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-citywide-stays', 'paris-best-hotels-and-hostels', 'Stay', 'France', 'Paris', null, '{"id":"list-paris-citywide-stays","slug":"paris-best-hotels-and-hostels","seoSlug":"best-hotels","seoTitle":"Best Hotels and Hostels in Paris","seoDescription":"Best places to stay in Paris, comparing palace hotels, Left Bank classics, Marais boutiques, Pigalle stays, canal hostels, and Belleville budget bases.","title":"Sleep by Arrondissement Fit","description":"Paris stay planning is an arrondissement decision before it is a brand decision: palace Seine views, Left Bank calm, Marais nightlife, Grands Boulevards convenience, Pigalle energy, or hostel bases near the canal and Belleville. Use this to match sleep style to route shape.","url":"https://www.google.com/maps/search/best+hotels+hostels+paris","category":"Stay","location":{"city":"Paris","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-stay","name":"R Stay","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"paris-stay-cheval-blanc","name":"Cheval Blanc Paris","coordinates":[48.8588,2.342],"description":"Cheval Blanc Paris is the Seine-facing luxury base for travelers who want palace-level service, Samaritaine access, and a central Right Bank position. It is best when the hotel is part of the trip, not just a bed between museum days.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://images.prismic.io/lvmh-chevalblanc/Z9AApRsAHJWomUFu_WebRGB-ChevalBlancParis_SuiteSeine_Jardind%27Hiver_511_VincentLeroux.jpg?auto=format,compress","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-cheval-blanc-paris"},{"id":"paris-stay-lutetia","name":"Hotel Lutetia","coordinates":[48.8517,2.327],"description":"Hotel Lutetia gives the citywide stay guide its grand Left Bank reference point, useful for Orsay, Luxembourg, Saint-Germain cafes, and polished cross-river days. Choose it when heritage and walkable calm matter more than immediate Marais nightlife.","price":"$$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://media.ffycdn.net/eu/mandarin-oriental-hotel-group/nsZ8J29W3zvRCSVUKdTY.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-lutetia"},{"id":"paris-stay-grand-mazarin","name":"Le Grand Mazarin","coordinates":[48.858,2.3546],"description":"Le Grand Mazarin is the citywide boutique-stay argument for sleeping in Le Marais, close to Hotel de Ville, galleries, restaurants, and late bars. It suits travelers who want old-center access with a design-forward mood rather than palace formality.","price":"$$$","priceSource":"Conde Nast Traveler / Vogue","photo":"https://www.legrandmazarin.com/wp-content/uploads/2024/07/hotel-le-grand-mazarin-piscine-hotel.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-le-grand-mazarin"},{"id":"paris-stay-hoxton","name":"The Hoxton Paris","coordinates":[48.87,2.3475],"description":"The Hoxton Paris is the Grands Boulevards base for travelers who want a lively lobby, covered-passage walks, and quick movement toward the 2nd, 9th, and Marais. It is less intimate than a small boutique hotel, but very practical.","price":"$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://thehoxton.com/wp-content/uploads/sites/5/2020/05/Paris_Hero.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-the-hoxton-paris"},{"id":"paris-stay-rochechouart","name":"Hotel Rochechouart","coordinates":[48.8822,2.3425],"description":"Hotel Rochechouart is the South Pigalle/Montmartre-edge choice when nightlife, rooftop views, and north-side browsing matter. Use it when you want easy evenings near Pigalle and Abbesses without sleeping on the busiest hilltop lanes.","price":"$$","priceSource":"Conde Nast Traveler / Google Travel","photo":"https://cdn.prod.website-files.com/6543b2c91ab677016dcd0684/67b4ac82da9fb02ce391077d_opengraph%20rochechouart.png","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-hotel-rochechouart"},{"id":"paris-stay-generator","name":"Generator Paris","coordinates":[48.8795,2.3696],"description":"Generator Paris is the design-hostel option near Canal Saint-Martin, with dorms, private rooms, and a social setup that makes sense for budget travelers. It fits travelers who value common spaces and canal access over old-city charm.","price":"$","priceSource":"Hostelworld / Google Maps","photo":"https://staygenerator.com/web/media/widget-spaces-rooms/paris/rooms-photos-2025/generator-paris-hostel-deluxe-king-room-1.jpg?mode=max&quality=100&v=202508261351","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-generator-paris"},{"id":"paris-stay-people-belleville","name":"The People Paris Belleville","coordinates":[48.8709,2.3773],"description":"The People Paris Belleville is the east-side hostel pick for travelers who want rooftop social energy, Belleville food, and fast metro access to the center. It is strongest for solo travelers and budget groups who actually plan to use the neighborhood.","price":"$","priceSource":"Hostelworld / Tripadvisor","photo":"https://www.thepeoplehostel.com/wp-content/uploads/2025/06/hostel-belleville-LesPiaules-shared_room_new-768x402.jpg","hours":{"default":"Reception and check-in details vary; confirm directly before booking."},"poiId":"poi-france-paris-the-people-paris-belleville"}],"sources":[{"name":"Conde Nast Traveler - Best hotels in Paris","url":"https://www.cntraveler.com/gallery/best-hotels-in-paris"},{"name":"Hostelworld - Paris hostels","url":"https://www.hostelworld.com/hostels/Paris"},{"name":"The Times - Best hotels in Paris 2026","url":"https://www.thetimes.com/travel/destinations/europe-travel/france/paris/best-hotels-in-paris-65dngr3zt"},{"name":"Tripadvisor - Paris hotels","url":"https://www.tripadvisor.com/Hotels-g187147-Paris_Ile_de_France-Hotels.html"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-top-parks-and-walks', 'paris-top-parks-and-walks', 'Nature', 'France', 'Paris', null, '{"id":"list-paris-top-parks-and-walks","slug":"paris-top-parks-and-walks","seoSlug":"best-parks","seoTitle":"Best Parks and Walks in Paris","seoDescription":"Best parks and walks in Paris for Luxembourg chairs, Tuileries and Seine routes, Buttes-Chaumont, Pere-Lachaise, Belleville views, and green east-side walks.","title":"Gardens, Cemeteries, and River Air","description":"Paris nature is about relief inside dense days: chair gardens, river walks, hill parks, cemeteries, elevated rail paths, and east-side viewpoints. Use this guide when the route needs air between museums, meals, and neighborhoods rather than a full day outside the city.","url":"https://www.google.com/maps/search/best+parks+walks+paris","category":"Nature","location":{"city":"Paris","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nature","name":"R Nature","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"paris-nature-luxembourg","name":"Jardin du Luxembourg","coordinates":[48.8462,2.3372],"description":"Jardin du Luxembourg gives the citywide nature guide its most useful Left Bank pause, linking Saint-Germain, the Latin Quarter, and museum days. Chairs, lawns, fountains, and palace views make it a practical reset rather than a nature detour.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-jardin-du-luxembourg"},{"id":"paris-nature-tuileries-seine","name":"Tuileries Garden and Seine Walk","coordinates":[48.8635,2.327],"description":"Tuileries and the Seine turn the Louvre-Orsay corridor into a walkable day instead of two disconnected museum bookings. Use the garden and river edges for pacing, light, and a low-effort reset between major indoor stops.","photo":"https://images.unsplash.com/photo-1508050919630-b135583b29ab?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-tuileries-garden-and-seine-walk"},{"id":"paris-nature-buttes-chaumont","name":"Parc des Buttes-Chaumont","coordinates":[48.8809,2.382],"description":"Buttes-Chaumont is the northeast hill-park choice, with dramatic slopes and local picnic energy even while sections undergo renovation. It belongs in the guide because it makes Belleville and La Villette days feel greener and less central.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-parc-des-buttes-chaumont"},{"id":"paris-nature-pere-lachaise","name":"Cimetiere du Pere-Lachaise","coordinates":[48.8614,2.3934],"description":"Pere-Lachaise is both cemetery and open-air museum, best approached as a slow leafy walk with a map rather than a quick celebrity-grave hunt. It pairs naturally with Belleville, Menilmontant, or the 11th after lunch.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-cimetiere-du-pere-lachaise"},{"id":"paris-nature-coulee-verte","name":"Coulee verte Rene-Dumont","coordinates":[48.8467,2.3754],"description":"Coulee verte Rene-Dumont gives Bastille and the 12th an elevated linear walk built from old rail infrastructure. It is the right choice when the day needs movement, greenery, and a quieter east-side route toward Reuilly or Vincennes.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-coulee-verte-rene-dumont"},{"id":"paris-nature-parc-belleville","name":"Parc de Belleville","coordinates":[48.8718,2.3843],"description":"Parc de Belleville gives the east a quick view payoff without the Sacre-Coeur crowd. Save it for a food-led Belleville plan, a sunset pause, or a simple way to understand the neighborhood''s slope and skyline.","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-parc-de-belleville"}],"sources":[{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-paris-weekend-activities', 'paris-weekend-activities', 'Activities', 'France', 'Paris', null, '{"id":"list-paris-weekend-activities","slug":"paris-weekend-activities","seoSlug":"best-things-to-do","seoTitle":"Best Things to Do in Paris for a Weekend","seoDescription":"Best things to do in Paris for a weekend, pacing museums, bistros, river walks, Marais wandering, Left Bank routes, the 7th, Belleville, and Montmartre.","title":"A Weekend With Museum Breathing Room","description":"This Paris activity guide turns the city into route blocks: one major museum, one Left Bank day, one Marais wander, one Eiffel-side culture path, and an east-side or Montmartre evening. It is built to prevent museum overload while still leaving room for meals and streets.","url":"https://www.google.com/maps/search/best+things+to+do+paris+weekend","category":"Activities","location":{"city":"Paris","country":"France","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-activities","name":"R Activities","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-07T00:00:00.000Z","stops":[{"id":"paris-activity-louvre-tuileries","name":"Louvre, Tuileries, and Palais Royal","coordinates":[48.8612,2.3376],"description":"Start with a bounded Louvre plan, then use Tuileries and Palais Royal as the breathing room around it. This stop keeps the first day central, scenic, and realistic without pretending the Louvre can be fully solved in one visit.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-louvre-tuileries-and-palais-royal"},{"id":"paris-activity-marais-vosges","name":"Le Marais and Place des Vosges","coordinates":[48.8567,2.365],"description":"Use Le Marais as the saved-map wandering day: Picasso or Carnavalet, Place des Vosges, Rue des Rosiers, boutiques, and a bistro or cocktail room. The point is density, not distance.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-le-marais-and-place-des-vosges"},{"id":"paris-activity-left-bank","name":"Saint-Germain and the Latin Quarter","coordinates":[48.8501,2.3385],"description":"Pair Saint-Germain polish with Latin Quarter history so the Left Bank becomes more than cafe lore: a brasserie, a bookshop, the Pantheon or Cluny, and Luxembourg Garden as the route''s soft landing.","photo":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-saint-germain-and-the-latin-quarter"},{"id":"paris-activity-orsay-rodin-eiffel","name":"Orsay, Rodin, and the Eiffel Side","coordinates":[48.8584,2.3126],"description":"This 7th-arrondissement route gives the Eiffel Tower context by surrounding it with Orsay, Rodin, Invalides, river walks, and one serious meal. It is best as a slow westward day, not a tower-only errand.","photo":"https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-orsay-rodin-and-the-eiffel-side"},{"id":"paris-activity-canal-belleville","name":"Canal Saint-Martin to Belleville","coordinates":[48.8725,2.3736],"description":"Build the east-side day from bakery and canal paths into Belleville food, Parc de Belleville, or a late jazz/electronic room. It keeps Paris current, local-feeling, and less museum-heavy.","photo":"https://images.unsplash.com/photo-1511739001486-6bfe10ce785f?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-canal-saint-martin-to-belleville"},{"id":"paris-activity-montmartre-pigalle","name":"Montmartre into South Pigalle","coordinates":[48.884,2.338],"description":"Make Montmartre a morning or golden-hour walk, then drop into South Pigalle for dinner, cocktails, or a show. This pacing keeps the hill from becoming a crowded postcard and gives the night a natural finish.","photo":"https://images.unsplash.com/photo-1539650116574-75c0c6d73f6e?auto=format&fit=crop&w=900&q=80","hours":{"default":"Hours, tickets, and access rules vary; confirm current details before visiting."},"poiId":"poi-france-paris-montmartre-into-south-pigalle"}],"sources":[{"name":"Louvre - Hours and admission","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Musee d''Orsay - Visit","url":"https://www.musee-orsay.fr/en/visit"},{"name":"Paris je t''aime - Place des Vosges","url":"https://parisjetaime.com/eng/transport/place-des-vosges-p1907"},{"name":"Sacre-Coeur Montmartre official","url":"https://www.sacre-coeur-montmartre.com/"},{"name":"Paris Opera - Visit the Palais Garnier","url":"https://www.operadeparis.fr/en/visits/visit-and-explore/visit-the-palais-garnier"},{"name":"Paris Catacombs official","url":"https://www.catacombes.paris.fr/en"},{"name":"Musee Rodin - Plan your visit","url":"https://www.musee-rodin.fr/en/plan-your-visit/plan-your-visit-musee-rodin"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Eater - Best Restaurants in Paris","url":"https://www.eater.com/maps/best-restaurants-paris-france"},{"name":"Eater - Paris","url":"https://www.eater.com/paris"},{"name":"The Infatuation - Paris","url":"https://www.theinfatuation.com/paris"},{"name":"The Infatuation - Le Marais","url":"https://www.theinfatuation.com/paris/neighborhoods/le-marais"},{"name":"MICHELIN Guide - Paris restaurants","url":"https://guide.michelin.com/us/en/ile-de-france/paris/restaurants"},{"name":"Time Out - Paris restaurants","url":"https://www.timeout.com/paris/en/restaurants"},{"name":"Google Maps","url":"https://maps.google.com"},{"name":"Ville de Paris - Parc des Buttes-Chaumont","url":"https://www.paris.fr/equipements/parc-des-buttes-chaumont-1757"},{"name":"Ville de Paris - Coulee verte Rene Dumont","url":"https://www.paris.fr/lieux/coulee-verte-rene-dumont-1772"},{"name":"Ville de Paris - Pere-Lachaise","url":"https://www.paris.fr/lieux/cimetiere-du-pere-lachaise-4080"},{"name":"Paris je t''aime - Pere-Lachaise","url":"https://parisjetaime.com/eng/paris-museum-monument/71470/Cimetiere-du-Pere-Lachaise"},{"name":"Louvre - Tuileries Garden hours","url":"https://www.louvre.fr/en/visit/hours-admission"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-london-soho-restaurants', 'london-soho-restaurants', 'Food', 'United Kingdom', 'London', 'Soho', '{"id":"list-london-soho-restaurants","slug":"london-soho-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in Soho, London","seoDescription":"Old central London counters, wine rooms, Thai grills, tapas bars, and vegetarian classics for eating well before theatre or late drinks.","title":"Theatreland Tables and Counter Heat","description":"London food works best when it is planned by area: markets, pubs, modern British rooms, South Asian routes, and reservations that respect tube time.","url":"https://www.google.com/maps/search/best%20restaurants%20in%20soho%2C%20london","category":"Food","location":{"city":"London","country":"United Kingdom","continent":"Europe","scope":"city","neighborhood":"Soho"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-10T00:00:00.000Z","stops":[{"id":"soho-food-noble-rot","name":"Noble Rot Soho","coordinates":[51.5126,-0.1318],"description":"Noble Rot gives Soho a wine-led modern British anchor: serious bottles, sharp cooking, and enough polish for a planned dinner without losing the neighborhood''s loose evening rhythm.","price":"$$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-noble-rot-soho"},{"id":"soho-food-kiln","name":"Kiln","coordinates":[51.5137,-0.1361],"description":"Kiln is the compact counter stop for northern Thai grills, clay-pot noodles, and a room that moves fast. Use it when Soho needs high-flavor food before theater or drinks.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-kiln"},{"id":"soho-food-barrafina-dean","name":"Barrafina Dean Street","coordinates":[51.5138,-0.1327],"description":"Barrafina Dean Street keeps Soho''s tapas energy direct and useful: counter seats, seafood, tortillas, sherry, and a no-fuss format that works between shows and late bars.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-barrafina-dean-street"},{"id":"soho-food-mildreds","name":"Mildreds Soho","coordinates":[51.5145,-0.1361],"description":"Mildreds is the practical Soho vegetarian classic, good for mixed groups who need a casual table with enough pace to stay useful on a central London route.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-mildreds-soho"},{"id":"soho-food-bao","name":"BAO Soho","coordinates":[51.5137,-0.1366],"description":"BAO Soho is small, efficient, and still one of the area''s best quick destination meals, especially when the plan needs a short, satisfying stop r