  ('list-london-soho-dive-bars', 'london-soho-dive-bars', 'Nightlife', 'United Kingdom', 'London', 'Soho', '{"id":"list-london-soho-dive-bars","slug":"london-soho-dive-bars","seoSlug":"best-dive-bars","seoTitle":"Best Dive Bars and Pubs in Soho, London","seoDescription":"Old pubs, jukebox rooms, jazz history, and low-lit Soho stops that keep the neighborhood grounded between cocktail reservations.","title":"Half-Pints, Jukeboxes, and Jazz","description":"London''s low-key drinking works through pubs, basement rooms, old regulars'' bars, and live-music spaces rather than one generic nightlife strip.","url":"https://www.google.com/maps/search/best%20dive%20bars%20and%20pubs%20in%20soho%2C%20london","category":"Nightlife","location":{"city":"London","country":"United Kingdom","continent":"Europe","scope":"city","neighborhood":"Soho"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%237c3aed%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-10T00:00:00.000Z","stops":[{"id":"soho-bar-french-house","name":"The French House","coordinates":[51.5127,-0.1326],"description":"The French House is the Soho regulars'' pub: half-pints, history, artists, theatre people, and a room that works best as a focused stop rather than a crawl filler.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https:/