  ('list-london-citywide-south-asian', 'london-best-south-asian-food-citywide', 'Food', 'United Kingdom', 'London', null, '{"id":"list-london-citywide-south-asian","slug":"london-best-south-asian-food-citywide","seoSlug":"best-restaurants","seoTitle":"Best South Asian Food in London","seoDescription":"Best South Asian and South Asian-influenced food routes in London, from Bombay cafe classics to market streets and central group meals.","title":"Spice Routes Across Central and East London","description":"London food works best when it is planned by area: markets, pubs, modern British rooms, South Asian routes, and reservations that respect tube time.","url":"https://www.google.com/maps/search/best%20south%20asian%20food%20in%20london","category":"Food","location":{"city":"London","country":"United Kingdom","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-10T00:00:00.000Z","stops":[{"id":"covent-food-dishoom","name":"Dishoom Covent Garden","coordinates":[51.5124,-0.1269],"description":"Dishoom Covent Garden is reliable for group-friendly Bombay cafe food, breakfast, and late meals in a part of town where dependable flexibility matters.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-dishoom-covent-garden"},{"id":"shoreditch-culture-brick-lane","name":"Brick Lane","coordinates":[51.5217,-0.0717],"description":"Brick Lane is the street-culture corridor for curry houses, markets, murals, vintage shops, and east London identity that should be walked rather than rushed.","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-brick-lane"},{"id":"southbank-food-borough-market","name":"Borough Market","coordinates":[51.5054,-0.0906],"description":"Borough Market is the South Bank area''s flexible food engine: grazing, produce, bakeries, and quick counters that work for groups without locking the day into one table.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1533929736458-ca588d08c8be?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-borough-market"},{"id":"soho-food-kiln","name":"Kiln","coordinates":[51.5137,-0.1361],"description":"Kiln is the compact counter stop for northern Thai grills, clay-pot noodles, and a room that moves fast. Use it when Soho needs high-flavor food before theater or drinks.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-kiln"},{"id":"shoreditch-food-smoking-goat","name":"Smoking Goat Shoreditch","coordinates":[51.5238,-0.0787],"description":"Smoking Goat is the high-impact casual stop for Thai drinking food, smoke, spice, and late energy. It fits when Shoreditch food should slide naturally into bars.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-smoking-goat-shoreditch"}],"sources":[{"name":"The Infatuation - Best Restaurants in London","url":"https://www.theinfatuation.com/london/guides/best-restaurants-london"},{"name":"Eater London - Essential London Restaurants","url":"https://london.eater.com/maps/best-restaurants-london-38"},{"name":"Michelin Guide - London restaurants","url":"https://guide.michelin.com/gb/en/greater-london/london/restaurants"}]}'::jsonb),
  ('list-london-citywide-popular-bars', 'london-best-popular-bars-citywide', 'Nightlife', 'United Kingdom', 'London', null, '{"id":"list-london-citywide-popular-bars","slug":"london-best-popular-bars-citywide","seoSlug":"best-bars","seoTitle":"Best Bars in London","seoDescription":"Best bars in London, from Soho cocktails and hotel classics to Shoreditch venues, west London pubs, and South Bank rooftops.","title":"Cocktails, Clubs, and Skyline Drinks","description":"Use this when the night needs stronger pull: cocktail rooms, hotel bars, live venues, theatre-adjacent drinks, and late rooms with a reason to cross town.","url":"https://www.google.com/maps/search/best%20bars%20in%20london","category":"Nightlife","location":{"city":"London","country":"United Kingdom","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%237c3aed%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-10T00:00:00.000Z","stops":[{"id":"soho-bar-swift","name":"Swift Soho","coordinates":[51.5136,-0.1327],"description":"Swift is the polished Soho cocktail pick, split between quick upstairs drinks and a more deliberate downstairs bar when the night has room to linger.","price":"$$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-swift-soho"},{"id":"covent-bar-american","name":"American Bar at The Savoy","coordinates":[51.5104,-0.1202],"description":"The American Bar is the heritage cocktail splurge, best used when the night wants ceremony and a sense of London hotel-bar history.","price":"$$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-american-bar-at-the-savoy"},{"id":"shoreditch-bar-happiness","name":"Happiness Forgets","coordinates":[51.5298,-0.0836],"description":"Happiness Forgets is the basement cocktail benchmark for a quieter, better-made Hoxton drink before the night gets louder.","price":"$$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-happiness-forgets"},{"id":"notting-bar-trailer","name":"Trailer Happiness","coordinates":[51.5162,-0.2049],"description":"Trailer Happiness gives Portobello a rum-soaked basement cocktail identity, ideal when Notting Hill needs a late stop with more personality than prettiness.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-trailer-happiness"},{"id":"southbank-bar-twelve-knot","name":"12th Knot","coordinates":[51.5081,-0.1069],"description":"12th Knot is the rooftop South Bank cocktail stop, strongest at sunset when the river and skyline are part of the reason to go.","price":"$$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-12th-knot"}],"sources":[{"name":"Time Out - Best bars in London","url":"https://www.timeout.com/london/bars-and-pubs/best-bars-in-london"},{"name":"The Infatuation - London bars","url":"https://www.theinfatuation.com/london/guides/best-bars-london"},{"name":"Resident Advisor - London events","url":"https://ra.co/events/uk/london"}]}'::jsonb),
  ('list-london-citywide-dive-bars', 'london-best-dive-bars-citywide', 'Nightlife', 'United Kingdom', 'London', null, '{"id":"list-london-citywide-dive-bars","slug":"london-best-dive-bars-citywide","seoSlug":"best-dive-bars","seoTitle":"Best Pubs and Dive Bars in London","seoDescription":"Best pubs and low-key bars in London, collecting old central rooms, east London music pubs, Portobello pints, and riverside stops.","title":"Old Pubs and Late Rooms","description":"London''s low-key drinking works through pubs, basement rooms, old regulars'' bars, and live-music spaces rather than one generic nightlife strip.","url":"https://www.google.com/maps/search/best%20pubs%20and%20dive%20bars%20in%20london","category":"Nightlife","location":{"city":"London","country":"United Kingdom","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%237c3aed%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-10T00:00:00.000Z","stops":[{"id":"soho-bar-french-house","name":"The French House","coordinates":[51.5127,-0.1326],"description":"The French House is the Soho regulars'' pub: half-pints, history, artists, theatre people, and a room that works best as a focused stop rather than a crawl filler.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-the-french-house"},{"id":"soho-bar-bradleys","name":"Bradley''s Spanish Bar","coordinates":[51.515,-0.1328],"description":"Bradley''s keeps Soho scruffy and useful, with jukebox energy, simple drinks, and the kind of late central-London feel polished cocktail rooms cannot fake.","price":"$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-bradley-s-spanish-bar"},{"id":"covent-bar-lamb-flag","name":"The Lamb & Flag","coordinates":[51.5114,-0.1259],"description":"The Lamb & Flag is the Covent Garden pub classic, tucked off the piazza with enough history and bustle to make it a strong pre-theatre pint.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-the-lamb-and-flag"},{"id":"shoreditch-bar-old-blue-last","name":"The Old Blue Last","coordinates":[51.5246,-0.0807],"description":"The Old Blue Last keeps Shoreditch tied to live music, beer, and late energy, making it a useful stop when the route wants a less polished room.","price":"$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-the-old-blue-last"},{"id":"southbank-bar-anchor","name":"The Anchor Bankside","coordinates":[51.5074,-0.0927],"description":"The Anchor Bankside is the riverside pub stop for views, history, and an easy pint between Borough Market and Tate Modern.","price":"$$","priceSource":"Editorial source review / Google Maps","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80","poiId":"poi-united-kingdom-london-the-anchor-bankside"}],"sources":[{"name":"Time Out - Best bars in London","url":"https://www.timeout.com/london/bars-and-pubs/best-bars-in-london"},{"name":"The Infatuation - London bars","url":"https://www.theinfatuation.com/london/guides/best-bars-london"},{"name":"Resident Advisor - London events","url":"https://ra.co/events/uk/london"}]}'::jsonb),
  ('list-london-citywide-culture', 'london-best-culture-citywide', 'Culture', 'United Kingdom', 'London', null, '{"id":"list-london-citywide-culture","slug":"london-best-culture-citywide","seoSlug":"best-culture","seoTitle":"Best Culture in London","seoDescription":"Best culture in London, linking museums, galleries, theatre, markets, modern art, and riverfront performance into a citywide route.","title":"Museums, Stages, and River Rooms","description":"Use this culture route to connect London''s museums, galleries, performance rooms, street history, and neighborhood texture without turning the day into a cross-town checklist.","url":"https://www.google.com/maps/search/best%20culture%20in%20london","category":"Culture","location":{"city":"London","country":"United Kingdom","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%23b45309%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-10T00:00:00.000Z","stops":[{"id":"soho-culture-british-museum","name":"British Museum","coordinates":[51.5194,-0.127],"description":"The British Museum gives the central route global collection weight, but it is best used with a tight plan so the day keeps moving toward Soho or Covent Garden.","hours":{"default":"Check current hours before going."},"photo":"https://images.unsplash.com/photo-1564324144208-0fba095a2ae5?auto=format&fit=crop&w=1600&q=80","poiI