  ('list-madrid-malasana-culture', 'madrid-malasana-culture', 'Culture', 'Spain', 'Madrid', 'Malasana', '{"id":"list-madrid-malasana-culture","slug":"madrid-malasana-culture","seoSlug":"best-culture","seoTitle":"Best Culture in Malasana, Madrid","seoDescription":"Best culture in Malasana, Madrid, from Museo de Historia and Plaza Dos de Mayo to Conde Duque, Teatro Lara, and Movida-era streets.","title":"Movida Memory and Neighborhood Stages","description":"Malasana culture is street-level: local history, uprising memory, independent theater, Conde Duque programming, and the lingering mythology of Madrid''s Movida.","url":"https://www.google.com/maps/search/malasana+madrid+culture","category":"Culture","location":{"city":"Madrid","neighborhood":"Malasana","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-culture","name":"R Culture","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"malasana-culture-history-museum","name":"Museo de Historia de Madrid","coordinates":[40.4259,-3.7009],"description":"Museo de Historia de Madrid tells the city''s story from its 16th-century court-capital rise through maps, paintings, models, prints, and everyday objects. The Baroque facade on Fuencarral also makes the museum feel connected to the street history of Malasana itself.","hours":{"mon":"Closed","tue":"10:00 AM-7:00 PM","wed":"10:00 AM-7:00 PM","thu":"10:00 AM-7:00 PM","fri":"10:00 AM-7:00 PM","sat":"10:00 AM-7:00 PM","sun":"10:00 AM-7:00 PM"},"photo":"https://estaticos.esmadrid.com/cdn/farfuture/s4kycL0wqQbfwpdoMYZ5v46zOq0dibShr8ZdRiwAun8/mtime:1524832499/sites/default/files/recursosturisticos/infoturistica/Museodehistoria663x335_1409746743.637.jpg","poiId":"poi-spain-madrid-museo-de-historia-de-madrid"},{"id":"malasana-culture-dos-mayo","name":"Plaza del Dos de Mayo","coordinates":[40.4266,-3.7045],"description":"Plaza del Dos de Mayo is Malasana''s symbolic square, named for the 1808 uprising against Napoleonic troops and marked by the monument to Daoiz and Velarde. It is also a lived neighborhood space, with cafe terraces, families, nightlife spillover, and the area''s independent character in plain view.","hours":{"mon":"Open public space","tue":"Open public space","wed":"Open public space","thu":"Open public space","fri":"Open public space","sat":"Open public space","sun":"Open public space"},"photo":"https://upload.wikimedia.org/wikipedia/commons/a/a8/Plaza_del_Dos_de_Mayo%2C_Madrid.jpg","poiId":"poi-spain-madrid-plaza-del-dos-de-mayo"},{"id":"malasana-culture-conde-duque","name":"Centro de Cultura Contemporánea Condeduque","coordinates":[40.4273,-3.7103],"description":"Centro de Cultura Contemporanea Condeduque fills a former royal guards barracks with contemporary exhibitions, concerts, theater, dance, film, talks, and festival programming. Its large courtyards and brick military architecture give Malasana a cultural center with real institutional scale.","hours":{"mon":"Closed","tue":"10:00 AM-7:00 PM","wed":"10:00 AM-7:00 PM","thu":"10:00 AM-7:00 PM","fri":"10:00 AM-7:00 PM","sat":"10:00 AM-7:00 PM","sun":"10:00 AM-7:00 PM"},"photo":"https://estaticos.esmadrid.com/cdn/farfuture/RHdtpU4v_49sNbLIEjWLrJSxgCAaS9DTNlfGzUsrLy4/mtime:1646729507/sites/default/files/styles/content_type_full/public/recursosturisticos/infoturistica/417051595_1072012135931_adj.jpg?itok=YDRDdC_X","poiId":"poi-spain-madrid-centro-de-cultura-contemporanea-condeduque"},{"id":"malasana-culture-teatro-lara","name":"Teatro Lara","coordinates":[40.4219,-3.7042],"description":"Teatro Lara has been operating since 1879, with a red-and-gold historic auditorium that keeps Malasana connected to Madrid''s small-theater tradition. Its program leans toward plays, comedy, music, and intimate stage work rather than monumental opera-house scale.","hours":{"mon":"Event schedule (check venue)","tue":"Event schedule (check venue)","wed":"Event schedule (check venue)","thu":"Event schedule (check venue)","fri":"Event schedule (check venue)","sat":"Event schedule (check venue)","sun":"Event schedule (check venue)"},"photo":"https://teatrolara.com/images/parallax.jpg","poiId":"poi-spain-madrid-teatro-lara"}],"sources":[{"name":"Tourism Madrid","url":"https://www.esmadrid.com/en"},{"name":"Tourism Madrid - Prado Museum","url":"https://www.esmadrid.com/en/tourist-information/museo-del-prado"},{"name":"Tourism Madrid - Reina Sofia Museum","url":"https://www.esmadrid.com/en/tourist-information/reina-sofia-museum"},{"name":"Museo Nacional del Prado - Opening Times","url":"https://www.museodelprado.es/en/visit/opening-times-and-prices"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-madrid-la-latina-restaurants', 'madrid-la-latina-restaurants', 'Food', 'Spain', 'Madrid', 'La Latina', '{"id":"list-madrid-la-latina-restaurants","slug":"madrid-la-latina-restaurants","seoSlug":"best-restaurants","seoTitle":"Best Restaurants in La Latina, Madrid","seoDescription":"Best restaurants in La Latina, Madrid, for Cava Baja tapas, market meals, old taverns, Sunday El Rastro stops, and classic Madrid lunches.","title":"Cava Baja Tapas and Old Taverns","description":"La Latina is Madrid''s easiest tapas neighborhood to romanticize, so the useful route mixes classics, market stops, and rooms that make sense before or after El Rastro.","url":"https://www.google.com/maps/search/la+latina+madrid+restaurants","category":"Food","location":{"city":"Madrid","neighborhood":"La Latina","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-food","name":"R Food","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"latina-food-juana-loca","name":"Juana La Loca","coordinates":[40.4113,-3.7115],"description":"A La Latina tapas anchor known for tortilla and a more polished Cava Baja meal than a random crawl stop. Use Juana La Loca when you want a compact local-feeling stop that can sit before drinks or sightseeing.","price":"$","priceSource":"The Infatuation / Google Maps","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://static.wixstatic.com/media/1aa0f7_0b697c156a8f469aaa022ac129c18011~mv2.jpeg/v1/fit/w_1279,h_852,q_90,enc_avif,quality_auto/1aa0f7_0b697c156a8f469aaa022ac129c18011~mv2","poiId":"poi-spain-madrid-juana-la-loca"},{"id":"latina-food-casa-lucio","name":"Casa Lucio","coordinates":[40.412,-3.7106],"description":"The classic old-Madrid dining room for huevos rotos and a splurge-leaning La Latina lunch or dinner. Use Casa Lucio when the meal should be a reservation anchor rather than a casual crawl stop.","price":"$","priceSource":"Time Out / Google Maps","hours":{"mon":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","tue":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","wed":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","thu":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM","fri":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sat":"12:30 PM-4:00 PM, 7:30 PM-11:30 PM","sun":"12:30 PM-4:00 PM, 7:30 PM-11:00 PM"},"photo":"https://casalucio.es/wp-content/uploads/2015/09/local_01","poiId":"poi-spain-madrid-casa-lucio"},{"id":"latina-food-taberna-concha","name":"Taberna La Concha","coordinates":[40.4115,-3.7114],"description":"A vermouth-and-tapas stop on Cava Baja for keeping the meal small, social, and neighborhood-specific. Use Taberna La Concha when you want a compact local-feeling stop that can sit before drinks or sightseeing.","price":"$","priceSource":"Google Maps / Tripadvisor","hours":{"mon":"12:00 PM-12:30 AM","tue":"12:00 PM-12:30 AM","wed":"12:00 PM-12:30 AM","thu":"12:00 PM-1:30 AM","fri":"12:00 PM-2:00 AM","sat":"12:00 PM-2:00 AM","sun":"12:00 PM-12:00 AM"},"photo":"http://www.laconchataberna.com/wp-content/uploads/2018/10/fondopag2","poiId":"poi-spain-madrid-taberna-la-concha"},{"id":"latina-food-mercado-cebada","name":"Mercado de la Cebada","coordinates":[40.4115,-3.7089],"description":"The market stop for a less formal La Latina food plan near the metro, plazas, and El Rastro approaches. Use Mercado de la Cebada when the group needs flexible grazing, uneven appetites, or a quick reset between sights.","price":"$","priceSource":"Google Maps / local guides","hours":{"mon":"12:00 PM-12:00 AM","tue":"12:00 PM-12:00 AM","wed":"12:00 PM-12:00 AM","thu":"12:00 PM-12:00 AM","fri":"12:00 PM-1:00 AM","sat":"12:00 PM-1:00 AM","sun":"12:00 PM-12:00 AM"},"photo":"https://www.mercadodelacebada.com/wp-content/uploads/2022/06/Planta-baja_Bier-pause","poiId":"poi-spain-madrid-mercado-de-la-cebada"}],"sources":[{"name":"The Infatuation - Best Restaurants in Madrid","url":"https://www.theinfatuation.com/madrid/guides/best-madrid-restaurants"},{"name":"The Infatuation - Best Tapas Spots in Madrid","url":"https://www.theinfatuation.com/madrid/guides/best-tapas-spots-madrid"},{"name":"MICHELIN Guide - Madrid restaurants","url":"https://guide.michelin.com/us/en/comunidad-de-madrid/madrid/restaurants"},{"name":"Time Out Madrid - Restaurants","url":"https://www.timeout.es/madrid/es/restaurantes"},{"name":"Google Maps","url":"https://maps.google.com"}]}'::jsonb),
  ('list-madrid-la-latina-popular-bars', 'madrid-la-latina-bars', 'Nightlife', 'Spain', 'Madrid', 'La Latina', '{"id":"list-madrid-la-latina-popular-bars","slug":"madrid-la-latina-bars","seoSlug":"best-bars","seoTitle":"Best Bars in La Latina, Madrid","seoDescription":"Best bars in La Latina, Madrid, including Cava Baja vermouth stops, rooftop drinks, tapas bars, and late rooms after El Rastro.","title":"Cava Baja Into the Night","description":"La Latina is best when drinks and food blur: vermouth, tapas, rooftop views, small rooms, and late stops that make sense after a Sunday market or old-city dinner.","url":"https://www.google.com/maps/search/la+latina+madrid+bars","category":"Nightlife","location":{"city":"Madrid","neighborhood":"La Latina","country":"Spain","continent":"Europe","scope":"city"},"creator":{"id":"user-rguide-nightlife","name":"R Nightlife","avatar":"data:image/svg+xml;utf8,%0A%20%20%20%20%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%0A%20%20%20%20%20%20%3Crect%20width%3D%22160%22%20height%3D%22160%22%20rx%3D%2280%22%20fill%3D%22%230f766e%22%20%2F%3E%0A%20%20%20%20%20%20%3Ctext%20x%3D%2250%25%22%20y%3D%2254%25%22%20text-anchor%3D%22middle%22%20dominant-baseline%3D%22middle%22%0A%20%20%20%20%20%20%20%20font-family%3D%22Arial%2C%20sans-serif%22%20font-size%3D%2276%22%20font-weight%3D%22700%22%20fill%3D%22white%22%3ER%3C%2Ftext%3E%0A%20%20%20%20%3C%2Fsvg%3E%0A%20%20"},"upvotes":0,"createdAt":"2026-05-06T00:00:00.000Z","stops":[{"id":"latina-nightlife-viajero","name":"El Viajero","coordinates":[40.4113,-3.711],"description":"El Viajero spreads La Latina nightlife across multiple floors, with street-level energy, indoor dining, and the rooftop terrace as the main prize. It works when the evening needs Cava Baja proximity, views, and a casual climb from tapas into drinks.","hours":{"mon":"12:00 PM-12:30 AM","tue":"12:00 PM-12:30 AM","wed":"12:00 PM-12:30 AM","t